/* Лёгкая пульсация имён (theme-standard): opacity 0.90 → 0.74 */
@keyframes name-pulse {
  0%, 100% { opacity: 0.9; }
  50% { opacity: 0.74; }
}

/* Моб.: вспышка — медленнее нарастание, дольше яркий пик, плавное затухание */
/* Смещение к центроиду контура звезды (viewBox 24×24, path как в GameTable) → в px при иконке 17px */
@keyframes exact-order-star-flash {
  0% {
    opacity: 0;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(0);
    filter: brightness(2.6) saturate(1.18) blur(2px);
  }
  12% {
    opacity: 1;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(0.55);
    filter: brightness(5.2) saturate(1.45) blur(0.35px);
  }
  26% {
    opacity: 1;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(1);
    filter: brightness(6.35) saturate(1.58) contrast(1.08) hue-rotate(-10deg) blur(0px);
  }
  52% {
    opacity: 1;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(1.06);
    filter: brightness(6.35) saturate(1.58) contrast(1.08) hue-rotate(-10deg) blur(0px);
  }
  72% {
    opacity: 0.38;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(1.42);
    filter: brightness(1.65) saturate(1.12) hue-rotate(0deg) blur(8px);
  }
  100% {
    opacity: 0;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(1.85);
    filter: brightness(1) saturate(1) hue-rotate(0deg) blur(20px);
  }
}

/* Ореол: тот же центроид; компактнее → меньше blur, выше brightness */
@keyframes exact-order-star-flash-halo {
  0% {
    opacity: 0;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(0.25);
    filter: blur(11px) brightness(1);
  }
  26% {
    opacity: 0.95;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(1);
    filter: blur(8px) brightness(1.52);
  }
  52% {
    opacity: 0.9;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(1.08);
    filter: blur(7px) brightness(1.46);
  }
  100% {
    opacity: 0;
    transform: translate(
        calc(-50% + var(--exact-order-star-flash-optical-x, 0px)),
        calc(-50% + var(--exact-order-star-flash-optical-y, 0px))
      )
      scale(2.05);
    filter: blur(16px) brightness(1);
  }
}

/* Моб.: появление звезды — дольше «пролёт» масштабом из центра (без translate) */
@keyframes exact-order-star-enter {
  0% {
    opacity: 0;
    transform: scale(0.04);
  }
  18% {
    opacity: 0.28;
    transform: scale(0.18);
  }
  40% {
    opacity: 0.65;
    transform: scale(0.48);
  }
  62% {
    opacity: 0.95;
    transform: scale(0.82);
  }
  78% {
    opacity: 1;
    transform: scale(1.03);
  }
  90% {
    opacity: 1;
    transform: scale(0.99);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* Моб.: обводка звезды — голубо-сиреневый неон, без белых пиков в цикле */
@keyframes exact-order-star-stroke-shimmer {
  0%,
  100% {
    color: #6d7fe8;
    stroke-opacity: 0.92;
  }
  32% {
    color: #9aa8ff;
    stroke-opacity: 1;
  }
  64% {
    color: #7c8ded;
    stroke-opacity: 0.97;
  }
}

/* Моб.: пульсация на SVG — заметнее opacity + brightness (тень остаётся на __enter, без scale — без шатания) */
@keyframes exact-order-star-pulse {
  0%,
  100% {
    opacity: 1;
    filter: brightness(1);
  }
  32% {
    opacity: 0.52;
    filter: brightness(1.52);
  }
  58% {
    opacity: 0.68;
    filter: brightness(1.2);
  }
}

@keyframes exact-order-star-pulse-soft {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.94;
  }
}

@keyframes exact-order-star-stroke-shimmer-soft {
  0%,
  100% {
    color: #6d7fe8;
    stroke-opacity: 0.92;
  }
  50% {
    color: #8494f5;
    stroke-opacity: 0.96;
  }
}

/* Моб. юг: вторая звезда на панели заказа — бирюзовый неон (обводка) */
@keyframes exact-order-star-stroke-shimmer-cyan {
  0%,
  100% {
    color: #06b6d4;
    stroke-opacity: 0.92;
  }
  32% {
    color: #cffafe;
    stroke-opacity: 1;
  }
  64% {
    color: #22d3ee;
    stroke-opacity: 0.97;
  }
}
@keyframes exact-order-star-stroke-shimmer-soft-cyan {
  0%,
  100% {
    color: #0891b2;
    stroke-opacity: 0.92;
  }
  50% {
    color: #5eead4;
    stroke-opacity: 0.98;
  }
}

/* Моб. юг: звезда «ровно в заказ» — прилёт справа (translateX), яркая вспышка */
@keyframes user-exact-order-star-fly-enter {
  0% {
    opacity: 0;
    transform: translateX(44px) scale(0.14) rotate(22deg);
  }
  52% {
    opacity: 1;
    transform: translateX(-7px) scale(1.14) rotate(-6deg);
  }
  76% {
    transform: translateX(4px) scale(0.96) rotate(2deg);
  }
  100% {
    opacity: 1;
    transform: translateX(0) scale(1) rotate(0deg);
  }
}

/* Прилёт в угол аватарки (снизу-справа к якорю) */
@keyframes user-exact-order-star-fly-enter-se {
  0% {
    opacity: 0;
    transform: translate(32px, 26px) scale(0.14) rotate(22deg);
  }
  52% {
    opacity: 1;
    transform: translate(-7px, -6px) scale(1.12) rotate(-6deg);
  }
  76% {
    transform: translate(4px, 3px) scale(0.96) rotate(2deg);
  }
  100% {
    opacity: 1;
    transform: translate(0, 0) scale(1) rotate(0deg);
  }
}

/* Прилёт в угол аватарки (снизу-слева к якорю) — зеркало SE */
@keyframes user-exact-order-star-fly-enter-sw {
  0% {
    opacity: 0;
    transform: translate(-32px, 26px) scale(0.14) rotate(-22deg);
  }
  52% {
    opacity: 1;
    transform: translate(7px, -6px) scale(1.12) rotate(6deg);
  }
  76% {
    transform: translate(-4px, 3px) scale(0.96) rotate(-2deg);
  }
  100% {
    opacity: 1;
    transform: translate(0, 0) scale(1) rotate(0deg);
  }
}

/* Прилёт в верхний правый угол панели заказа (сверху-снаружи к якорю) */
@keyframes user-exact-order-star-fly-enter-ne {
  0% {
