  }
  76% {
    transform: translate(4px, -3px) scale(0.96) rotate(-3deg);
  }
  100% {
    opacity: 1;
    transform: translate(0, 0) scale(1) rotate(0deg);
  }
}

/* Тот же прилёт, короче траектория — под SVG ×13 (≈19/1.5) на панели заказа */
@keyframes user-exact-order-star-fly-enter-ne-compact {
