  }
  @keyframes standard-hand-playable-pulse {
    0%,
    100% {
      filter: brightness(1);
    }
    50% {
      filter: brightness(1.07);
    }
  }
  @keyframes dark-hand-playable-pulse {
    0%,
    100% {
      filter: brightness(1);
    }
    50% {
      filter: brightness(1.1);
    }
  }
  /* Черные масти (пики, крести): без мерцания у правого нижнего индекса */
  .game-table-root .card-ace-suit-index-mobile.card-ace-suit-black {
    position: relative;
    animation: none;
  }
  .game-table-root .card-ace-suit-index-mobile.card-ace-suit-black::after {
