    50% {
      text-shadow: 0 0 8px currentColor, 0 0 14px currentColor, 0 0 20px rgba(255, 255, 255, 0.4);
      filter: brightness(1.15);
    }
  }
  @keyframes ace-suit-center-pulse-black {
    0%, 100% {
      opacity: 0.45;
      transform: translate(-50%, -50%) scale(0.85);
    }
    50% {
      opacity: 0.85;
      transform: translate(-50%, -50%) scale(1.1);
    }
  }

  /* Центральный рисунок туза: контур и выпуклость только по форме картинки (drop-shadow по альфе) */
  .game-table-root .card-ace-central-img {
