}
.game-table-root.game-table-seats-three-pc:not(.viewport-mobile)
  .ai-difficulty-header-right-slot
  .ai-difficulty-trigger-label {
  display: inline-block !important;
  flex-shrink: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 12px !important;
  font-weight: 800 !important;
  letter-spacing: 0.04em !important;
  line-height: 1 !important;
  color: rgb(165 243 252 / 96%) !important;
  -webkit-text-fill-color: rgb(165 243 252 / 96%) !important;
  background: none !important;
