}
.table-chat-dock--pro .table-chat-emoji-more {
  flex-shrink: 0;
  width: 100%;
  margin: 0;
  padding: 5px 8px;
  border-radius: 8px;
  border: 1px dashed rgba(100, 116, 139, 0.55);
  background: rgba(30, 41, 59, 0.45);
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  font: inherit;
}
.table-chat-dock--pro .table-chat-emoji-more:hover {
  border-color: rgba(34, 211, 238, 0.45);
  color: #e2e8f0;
}
.table-chat-dock--pro .table-chat-phrase-scroll {
  max-height: min(32vh, 168px);
  overflow-y: auto;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  gap: 4px;
