  scrollbar-color: rgba(34, 211, 238, 0.35) transparent;
}
.table-chat-dock--pro .table-chat-phrase-row {
  display: flex;
  gap: 4px;
  align-items: stretch;
}
.table-chat-dock--pro .table-chat-phrase-row .table-chat-phrase-btn {
  flex: 1;
  min-width: 0;
}
.table-chat-dock--pro .table-chat-add-mine-mini {
  flex-shrink: 0;
  width: 30px;
  padding: 0;
  border-radius: 8px;
  border: 1px solid rgba(34, 211, 238, 0.38);
