  color: #7dd3fc;
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  font: inherit;
  box-shadow:
    0 0 0 1px rgba(167, 139, 250, 0.38),
    inset 0 0 0 1px rgba(221, 214, 254, 0.2);
}
.table-chat-dock--pro .table-chat-add-mine-mini:hover:not(:disabled) {
