  /*
   * Phone landscape (не mid 601–899) · 4p:
   * З/В — 6px от края страницы, 4px от стола; стол на остаток ширины;
   * тулбар слева с отступом 6px; имя В/З внутри панели (не на сукне).
   */
  .game-table-root.viewport-mobile.viewport-mobile-landscape:not(.viewport-mobile-landscape-mid) {
    --landscape-phone-page-edge: 6px;
    --landscape-we-panel-edge-pad: 0px;
    /* Зазор З/В ↔ стол задаём gap ряда (не margin слота — иначе ширина панели «плывёт») */
    --landscape-we-panel-table-margin: 0px;
    --game-table-landscape-board-gap: 4px;
    --landscape-upper-row-shift-left: 0px;
    --landscape-we-avatar-size: 60px;
    --landscape-we-avatar-reserve: 64px;
    /* Тулбар+бейдж: базовый размер phone LS (−5%); сжатие — .viewport-mobile-landscape-after-short */
    --ls-cluster-compact: 0.95;
    --landscape-upper-rail-w: 152px; /* 160 × 0.95 */
    --ls-badge-w: 190px;
    /* −1px: gap meta↔экранчик 2→1, экранчик поднимается, низ бейджа короче */
    --mobile-landscape-upper-badge-h: 63.84px; /* +1px снизу */
    --landscape-toolbar-btn-size: 30.4px; /* 32 × 0.95 */
    --game-table-landscape-side-col-max: var(--landscape-we-panel-fixed-w, 108px);
    --game-table-landscape-table-col-width: calc(
      100% - 2 * var(--landscape-we-panel-fixed-w, 108px)
        - 2 * var(--game-table-landscape-board-gap, 4px)
        - 2 * var(--landscape-phone-page-edge, 6px)
    );
    /* Instrument ensemble: тулбар ↔ HUD ↔ сукно (одна космическая система) */
    --ls-chassis-violet: #7c3aed;
    --ls-chassis-indigo: #6366f1;
    --ls-chassis-cyan: #22d3ee;
    --ls-chassis-cyan-deep: #0891b2;
    --ls-chassis-ice: #a5f3fc;
    --ls-chassis-rail: rgba(34, 211, 238, 0.75);
    --ls-chassis-r: 11.4px;
    --ls-module-r: 9.5px;
    --ls-screen-r: 7.6px;
    --ls-chassis-mod-gap: 11.4px;
    --ls-chassis-bus-w: 3px;
    --ls-chassis-drop-h: 16px;
    --ls-chassis-edge: linear-gradient(
      125deg,
      #4c1d95 0%,
      #6d28d9 14%,
      #7c3aed 28%,
      #22d3ee 46%,
      #67e8f9 58%,
      #6366f1 72%,
      #a78bfa 86%,
      #22d3ee 100%
    );
    --ls-chassis-glow:
      0 0 10px rgba(34, 211, 238, 0.4),
      0 0 22px rgba(124, 58, 237, 0.32),
      0 0 34px rgba(34, 211, 238, 0.16),
      0 6px 18px rgba(3, 7, 18, 0.5);
    --ls-chassis-void:
      radial-gradient(1.2px 1.2px at 14% 22%, rgba(255, 255, 255, 0.75) 0%, transparent 100%),
      radial-gradient(1px 1px at 72% 18%, rgba(165, 243, 252, 0.8) 0%, transparent 100%),
      radial-gradient(1.1px 1.1px at 48% 78%, rgba(216, 180, 254, 0.65) 0%, transparent 100%),
      radial-gradient(0.9px 0.9px at 88% 62%, rgba(255, 255, 255, 0.45) 0%, transparent 100%),
      linear-gradient(
        155deg,
        rgba(6, 10, 28, 0.94) 0%,
        rgba(12, 8, 36, 0.92) 40%,
        rgba(4, 14, 30, 0.94) 100%
      );
  }

  /*
   * Phone LS после short / immersive / «стандарт после short»:
   * тулбар уже по ширине; бейдж заметно компактнее обычного phone LS (~−15%).
   * (раньше инлайн width:190 в GameTable блокировал CSS — снято.)
   */
  .game-table-root.viewport-mobile.viewport-mobile-landscape.viewport-mobile-landscape-after-short:not(
      .viewport-mobile-landscape-mid
    ) {
    /* Тулбар: 4 кнопки чуть меньше + место под экранчик; шрифт экранчика не трогаем */
    --landscape-upper-rail-w: 136px;
    --landscape-toolbar-btn-size: 24px;
    --ls-badge-w: 162px; /* 190 × 0.85 */
    --mobile-landscape-upper-badge-h: 58px;
    /* Только after-short: край + стык модулей (обычный phone LS не трогаем) */
    --landscape-phone-page-edge: 0px;
    --ls-chassis-mod-gap: 0px;
    --ls-chassis-bus-w: 2px;
  }

  /*
   * Phone LS (не mid) · умные кольца (С/З/В/Юг): padding вдвое тоньше (!important бьёт inline).
   * Лицо крупнее на ту же сумму — в GameTable (внешний Ø прежний).
   */
  .game-table-root.viewport-mobile.viewport-mobile-landscape:not(.viewport-mobile-landscape-mid)
    .opponent-avatar-order-ring {
    padding: 3px !important;
  }
  .game-table-root.viewport-mobile.viewport-mobile-landscape:not(.viewport-mobile-landscape-mid)
    .user-player-panel
    .opponent-avatar-order-ring--exact {
    padding: 2.5px !important;
  }
  .game-table-root.viewport-mobile.viewport-mobile-landscape:not(.viewport-mobile-landscape-mid)
    .user-player-panel
    .opponent-avatar-order-ring--chasing {
    padding: 2px !important;
  }
  /*
   * Phone LS · лицо:
   * · с умным кольцом — 46 (+6), pad 3 → внешний ≈52;
   * · на торгах без кольца — 52, чтобы совпасть с внешним Ø в розыгрыше.
   * (Правила вне media max-height:651 — иначе на части phone LS не срабатывали.)
   */
  .game-table-root.viewport-mobile.viewport-mobile-landscape:not(.viewport-mobile-landscape-mid)
    .opponent-slot:not(:has(.opponent-avatar-order-ring))
