}
.game-table-root .opponent-avatar-order-ring--chasing {
  position: relative;
  isolation: isolate;
  /* Tie-dye: полукруговой conic + цветные «узлы»; вращение — ::after */
  background:
    radial-gradient(circle at 72% 26%, rgba(251, 113, 133, 0.58) 0%, transparent 46%),
    radial-gradient(circle at 22% 70%, rgba(129, 140, 248, 0.54) 0%, transparent 44%),
    radial-gradient(circle at 58% 80%, rgba(251, 146, 60, 0.52) 0%, transparent 46%),
    radial-gradient(circle at 34% 30%, rgba(232, 121, 250, 0.5) 0%, transparent 40%),
    radial-gradient(circle at 50% 48%, rgba(255, 255, 255, 0.45) 0%, transparent 38%),
    conic-gradient(
      from 36deg at 48% 50%,
      #fff8f4,
      #ffedd5,
      #fde68a,
      #fdba74,
      #fb923c,
      #fb7185,
      #f472b6,
      #e879f9,
      #c084fc,
      #a78bfa,
      #93c5fd,
      #fde68a,
      #fff8f4
    );
  /* Меньше слоёв и альфа — без «засвета» ободка (особенно снизу справа) */
  box-shadow:
    0 0 8px rgba(253, 186, 116, 0.34),
    0 0 14px rgba(251, 146, 60, 0.28),
    0 0 18px rgba(249, 115, 22, 0.22),
