      inset 0 0 12px rgba(94, 234, 212, 0.22),
      inset 0 1px 0 rgba(186, 230, 253, 0.7);
    border-color: rgba(125, 211, 252, 1);
  }
}
@keyframes bidBadgeTextPulseNarrow {
  0%, 100% {
    color: #7dd3fc;
    -webkit-text-fill-color: #7dd3fc;
    text-shadow:
      0 1px 2px rgba(0, 0, 0, 0.7),
      0 0 5px rgba(125, 211, 252, 1),
      0 0 12px rgba(56, 189, 248, 1),
