@keyframes bidBadgeFramePulse {
  0%, 100% {
    box-shadow: 0 0 4px rgba(34, 211, 238, 0.25), inset 0 0 14px rgba(34, 211, 238, 0.2), inset 0 1px 0 rgba(34, 211, 238, 0.35);
