    border-color: rgba(34, 211, 238, 1);
  }
}
@keyframes bidBadgeTextPulse {
  /* Голубой → фиолетовый → голубой; fill в ключах синхронен с color (WebKit иначе тянет :root почти белый при анимации только color) */
  0%, 100% {
    color: #38bdf8;
