.game-table-root.viewport-mobile .bid-panel-mobile-inline .bid-panel-mobile-grid.bid-panel-mobile-grid--rows {
  /*
   * Дефолт: база 44 (portrait / mid). Compact+ 41 — класс .bid-panel-mobile--compact41
   * и/или phone landscape :not(.mid) ниже.
   */
  --bid-btn-base: calc(44px * 1.05 * 1.07 * 1.02);
  --bid-gap-min: 6px;
  --bid-row-max: calc(6 * var(--bid-btn-base) + 5 * var(--bid-gap-min));
  --bid-fill-cols: 5;
  display: flex !important;
  flex-direction: column-reverse !important;
  flex-wrap: nowrap !important;
  align-items: stretch !important;
