  max-width: min(100%, var(--bid-row-max)) !important;
  min-width: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  margin-top: -12px !important;
  margin-bottom: -8px !important;
  padding: 12px 3px 10px !important;
  box-sizing: border-box !important;
  gap: 10px !important;
  overflow: visible !important;
  align-self: flex-end !important;
}
.game-table-root.viewport-mobile .bid-panel-mobile-inline .bid-panel-mobile-grid--rows .bid-panel-mobile-grid-row {
  display: flex;
  flex-direction: row-reverse;
  flex-wrap: nowrap;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow: visible;
  /* один размер на все ряды: (ширина − gaps) / fill-cols, ≤ 44 */
  --bid-btn-w: min(
    var(--bid-btn-base),
    calc((100% - (var(--bid-fill-cols) - 1) * var(--bid-gap-min)) / var(--bid-fill-cols))
  );
  /* жидкий gap от базы 44; при узком столе — gapMin (кнопки уже сжаты через --bid-btn-w) */
  gap: max(
    var(--bid-gap-min, 6px),
    calc((100% - var(--bid-fill-cols) * var(--bid-btn-base, 44px)) / (var(--bid-fill-cols) - 1))
  );
  justify-content: flex-start;
}
/* Мобилка · только нижний ряд: если кнопок ≤4 — не сжимать, всегда база */
