  .bid-panel-btn:not(:disabled):hover {
    transform: scale(1.02);
  }
  .bid-panel-inline .bid-panel-btn:not(:disabled):hover {
    transform: scale(1.02);
  }
}

/* Панель «Ваш заказ»: на планшете и мобильных — внутри панели игрока */
.bid-panel-floating {
  display: flex;
}
.bid-panel-inline {
  display: none;
}
@media (max-width: 1280px) {
  .bid-panel-floating {
    display: none !important;
  }
  .bid-panel-inline {
    display: flex !important;
  }
  .bid-panel-inline.bid-panel {
    padding: 4px 8px !important;
    gap: 6px !important;
  }
  .bid-panel-floating.bid-panel {
    padding: 10px 12px !important;
    gap: 4px !important;
    left: 12px !important;
    bottom: 12px !important;
  }
  .bid-panel-subtitle {
    display: none !important;
  }
  .bid-panel .bid-panel-title {
    font-size: 16px !important;
    margin-bottom: 0 !important;
  }
  .bid-panel-inline .bid-panel-title-inline {
    font-size: 12px !important;
  }
  .bid-panel-grid {
    gap: 4px !important;
    flex-wrap: nowrap !important;
    max-width: none !important;
  }
  /* Размеры on-table задают cosmic/PC правила; legacy — только floating */
  .bid-panel-floating .bid-panel-btn {
    width: 32px !important;
    height: 32px !important;
    font-size: 15px !important;
    padding: 0 !important;
  }
}
@media (max-width: 600px), (max-width: 1024px) and (max-height: 500px) and (min-aspect-ratio: 1.9), (min-width: 601px) and (max-width: 899px) {
  .bid-panel-inline.bid-panel {
    padding: 4px 6px !important;
    gap: 4px !important;
  }
  .bid-panel-floating.bid-panel {
    left: 8px !important;
    bottom: 8px !important;
  }
  .bid-panel .bid-panel-title {
    font-size: 14px !important;
  }
  .bid-panel-grid {
    gap: 3px !important;
    flex-wrap: nowrap !important;
    max-width: none !important;
  }
  .bid-panel-floating .bid-panel-btn {
    width: 28px !important;
    height: 28px !important;
    font-size: 14px !important;
  }
}

