 * Базовые rgba из gameInfoModePanelStyle: indigo 99,102,241; варианты — свои !important ниже.
 */
.game-table-root:not(.viewport-mobile) .game-header .game-info-mode-panel--pc-chrome {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  backdrop-filter: blur(8px) saturate(1.1);
  -webkit-backdrop-filter: blur(8px) saturate(1.1);
  border-radius: 9px !important;
  padding: 5px 8px 6px !important;
  gap: 4px !important;
  --gip-chrome-accent: rgba(99, 102, 241, 0.65);
  --gip-chrome-rail: rgba(129, 140, 248, 0.85);
  --gip-chrome-rail-dim: rgba(99, 102, 241, 0.35);
  --gip-chrome-inset: rgba(99, 102, 241, 0.12);
  --gip-corner-arm: 10px;
  --gip-corner-thick: 1px;
  --gip-corner-inset: 4px;
  --gip-led-tl: #22d3ee;
  --gip-led-tr: #a78bfa;
  --gip-led-bl: #6366f1;
  --gip-led-br: #f472b6;
  box-shadow:
    inset 1px 0 0 var(--gip-chrome-rail-dim),
    inset -1px 0 0 var(--gip-chrome-rail-dim),
    inset 0 -1px 0 var(--gip-chrome-rail-dim),
    inset 0 0 0 1px rgba(255, 255, 255, 0.05);
}

/* L-скобы + лёгкий верхний блик; LED — отдельные элементы ниже */
.game-table-root:not(.viewport-mobile) .game-header .game-info-mode-panel--pc-chrome::before {
  content: '';
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  background:
    linear-gradient(90deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) var(--gip-corner-inset) var(--gip-corner-inset) /
      var(--gip-corner-arm) var(--gip-corner-thick) no-repeat,
    linear-gradient(180deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) var(--gip-corner-inset) var(--gip-corner-inset) /
      var(--gip-corner-thick) var(--gip-corner-arm) no-repeat,
    linear-gradient(270deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) calc(100% - var(--gip-corner-inset))
      var(--gip-corner-inset) / var(--gip-corner-arm) var(--gip-corner-thick) no-repeat,
    linear-gradient(180deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) calc(100% - var(--gip-corner-inset))
      var(--gip-corner-inset) / var(--gip-corner-thick) var(--gip-corner-arm) no-repeat,
    linear-gradient(90deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) var(--gip-corner-inset)
      calc(100% - var(--gip-corner-inset)) / var(--gip-corner-arm) var(--gip-corner-thick) no-repeat,
    linear-gradient(0deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) var(--gip-corner-inset)
      calc(100% - var(--gip-corner-inset)) / var(--gip-corner-thick) var(--gip-corner-arm) no-repeat,
    linear-gradient(270deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) calc(100% - var(--gip-corner-inset))
      calc(100% - var(--gip-corner-inset)) / var(--gip-corner-arm) var(--gip-corner-thick) no-repeat,
    linear-gradient(0deg, var(--gip-chrome-rail) 0 var(--gip-corner-arm), transparent) calc(100% - var(--gip-corner-inset))
      calc(100% - var(--gip-corner-inset)) / var(--gip-corner-thick) var(--gip-corner-arm) no-repeat,
    linear-gradient(180deg, rgba(255, 255, 255, 0.06) 0%, transparent 42%);
  opacity: 0.9;
}

/* Верхняя неоновая рейка */
.game-table-root:not(.viewport-mobile) .game-header .game-info-mode-panel--pc-chrome::after {
  content: '';
  pointer-events: none;
  position: absolute;
  left: 14px;
  right: 14px;
  top: 0;
  z-index: 1;
  height: 1px;
  border-radius: 0 0 2px 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--gip-chrome-rail-dim) 18%,
    var(--gip-chrome-rail) 50%,
    var(--gip-chrome-rail-dim) 82%,
    transparent 100%
  );
  box-shadow: 0 0 6px var(--gip-chrome-accent);
  opacity: 0.95;
}

/* Угловые LED: 4 цвета, на вершине L-скоб, без белых точек */
.game-table-root:not(.viewport-mobile) .game-header .game-info-mode-panel__led {
  pointer-events: none;
  position: absolute;
