/* Мини-эхо последней взятки: стеклянная капсула НАД столом; выше полёта Σ */
.last-trick-echo {
  position: absolute;
  left: 50%;
  z-index: 160;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 22px 14px;
  border-radius: 20px;
  pointer-events: none;
  transform: translateX(-50%);
  background: linear-gradient(
    155deg,
    rgba(15, 23, 42, 0.78) 0%,
    rgba(49, 46, 129, 0.58) 48%,
    rgba(8, 47, 73, 0.68) 100%
  );
  border: 1px solid rgba(103, 232, 249, 0.45);
  box-shadow:
    0 12px 28px rgba(7, 10, 26, 0.42),
    0 0 0 1px rgba(167, 139, 250, 0.22),
    0 0 22px rgba(34, 211, 238, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(8px) saturate(1.2);
  -webkit-backdrop-filter: blur(8px) saturate(1.2);
  animation: lastTrickEchoIn 0.45s ease-out both;
  isolation: isolate;
}
.last-trick-echo--pc {
  position: fixed !important;
  /* Под шапкой, НАД поверхностью стола */
  top: max(64px, calc(env(safe-area-inset-top, 0px) + 52px)) !important;
  bottom: auto !important;
  left: 50% !important;
  min-width: 248px;
  z-index: 160 !important;
}
.last-trick-echo--mobile {
  position: fixed;
  top: max(12px, env(safe-area-inset-top, 0px));
  z-index: 16;
  min-width: 224px;
  padding: 18px 18px 12px;
}
.last-trick-echo--winner {
  border-color: rgba(110, 231, 249, 0.78);
  box-shadow:
    0 12px 28px rgba(7, 10, 26, 0.42),
    0 0 0 1px rgba(167, 139, 250, 0.28),
    0 0 28px rgba(34, 211, 238, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}
.last-trick-echo__rail {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 12px;
  flex-wrap: nowrap;
  /* Запас сверху под приподнятую карту взявшего */
  padding-top: 18px;
  padding-bottom: 2px;
}
.last-trick-echo__slot {
  margin: 0;
  flex: 0 0 auto;
  width: auto;
  line-height: 0;
  isolation: isolate;
  filter: drop-shadow(0 4px 8px rgba(0, 0, 0, 0.35));
  transition: transform 0.25s ease;
}
.last-trick-echo__slot:first-child {
  margin-left: 0;
}
.last-trick-echo__slot--winner {
  transform: translateY(-8px) scale(1.05);
  filter:
    drop-shadow(0 0 10px rgba(34, 211, 238, 0.55))
    drop-shadow(0 4px 8px rgba(0, 0, 0, 0.35));
}
.last-trick-echo--mine {
  border-color: rgba(52, 211, 153, 0.75);
}
.last-trick-echo--mine .last-trick-echo__winner {
  background: linear-gradient(90deg, #6ee7b7 0%, #67e8f9 55%, #a78bfa 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
}
.last-trick-echo__kicker {
  font-family: 'Exo 2', system-ui, sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  /* Fallback, если clip не сработает — всё равно кислотный розово-оранжевый */
  color: #ff3db5;
  background: linear-gradient(90deg, #ff6b2d 0%, #ff2d95 38%, #ff4fd8 72%, #ff9f1a 100%);
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: none;
  /* Лёгкий лазерный ореол — без сильной «замыленности» */
  filter:
    drop-shadow(0 0 1.5px rgba(255, 45, 149, 0.85))
    drop-shadow(0 0 4px rgba(255, 107, 45, 0.4));
  animation: lastTrickEchoLaserKicker 2.4s linear infinite;
}
@keyframes lastTrickEchoLaserKicker {
  0% {
    background-position: 0% 50%;
  }
  100% {
    background-position: 220% 50%;
  }
}

/* Карта взявшего на столе во время reveal/slots */
.last-trick-table-card--winner {
  filter:
    drop-shadow(0 0 0 2px rgba(34, 197, 94, 0.95))
