      drop-shadow(0 0 12px rgba(52, 211, 153, 0.55))
      drop-shadow(0 0 22px rgba(34, 211, 238, 0.28));
  }
  50% {
    filter:
      drop-shadow(0 0 0 3px rgba(110, 231, 249, 0.95))
      drop-shadow(0 0 18px rgba(52, 211, 153, 0.85))
