    rgba(30, 27, 75, 0.88) 48%,
    rgba(8, 47, 73, 0.9) 100%
  );
  border: 1px solid rgba(167, 139, 250, 0.5);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
    0 0 0 1px rgba(15, 23, 42, 0.5),
    0 6px 16px rgba(7, 10, 26, 0.4),
    0 0 16px rgba(129, 140, 248, 0.18);
}
.last-trick-echo__winner {
  font-family: 'Exo 2', system-ui, sans-serif;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.15;
  background: linear-gradient(90deg, #67e8f9 0%, #a78bfa 48%, #818cf8 100%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: lastTrickEchoSheen 5.5s linear infinite;
}
@keyframes lastTrickEchoIn {
  from {
    opacity: 0;
    transform: translateX(-50%) translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}
@keyframes lastTrickEchoSheen {
  0% {
    background-position: 0% 50%;
  }
  100% {
    background-position: 200% 50%;
  }
}

