/* Цифры: тускло ↔ как после 28 раздач (цвета только в CSS, без keyframes) */
.deal-results-sticky-payout-values__digit--veil-pulse.deal-results-sticky-payout-values__digit--pos {
  color: #b45309;
  -webkit-text-fill-color: #b45309;
  text-shadow: 0 0 6px rgb(251 191 36 / 0.22);
  transition:
    color 0.7s cubic-bezier(0.55, 0, 0.95, 0.2),
    -webkit-text-fill-color 0.7s cubic-bezier(0.55, 0, 0.95, 0.2),
    text-shadow 0.7s cubic-bezier(0.55, 0, 0.95, 0.2);
}
