  color: #fde047;
  -webkit-text-fill-color: #fde047;
  text-shadow: 0 0 9px rgb(251 191 36 / 0.62), 0 0 18px rgb(251 191 36 / 0.62);
  transition:
    color 4s cubic-bezier(0.22, 0.61, 0.36, 1),
    -webkit-text-fill-color 4s cubic-bezier(0.22, 0.61, 0.36, 1),
    text-shadow 4s cubic-bezier(0.22, 0.61, 0.36, 1);
}
