/* Индикатор «можно прокрутить»: стрелка вниз, лёгкая анимация */
.deal-results-table-scroll-hint-chevron {
  animation: dealResultsScrollHintBounce 1.8s ease-in-out infinite;
}
@keyframes dealResultsScrollHintBounce {
  0%, 100% { transform: translateY(0); opacity: 1; }
  50% { transform: translateY(6px); opacity: 0.9; }
}

.trick-slots-collecting {
  opacity: 0.4;
  transition: opacity 0.4s ease-out;
}
.trick-slots-normal {
  opacity: 1;
  transition: opacity 0.3s ease-in;
}

@keyframes dealResultsFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/*
 * ПК: схлопывание оверлея к кнопке Σ в шапке — те же --deal-results-collapse-dx/dy.
 * translateX(-50%) сохраняем (якорь left:50%), иначе скачок в начале полёта.
 */
@keyframes dealResultsCollapsePC {
  0% {
    transform: translateX(-50%)
      translate(0, 0)
      scale(var(--deal-results-overlay-scale, 0.96));
    border-radius: 20px;
    opacity: 1;
  }
  42% {
    transform: translateX(-50%)
      translate(
        calc(var(--deal-results-collapse-dx, 0px) * 0.42),
        calc(var(--deal-results-collapse-dy, 0px) * 0.42)
      )
      scale(calc(var(--deal-results-overlay-scale, 0.96) * 0.14));
    border-radius: 50%;
    opacity: 1;
  }
  100% {
    transform: translateX(-50%)
      translate(var(--deal-results-collapse-dx, 0px), var(--deal-results-collapse-dy, 0px))
      scale(calc(var(--deal-results-overlay-scale, 0.96) * 0.052));
    border-radius: 50%;
    opacity: 0.9;
  }
}

/*
 * Схлопывание мобильного оверлея к реальной Σ: вектор в px задаётся с корня портала
 * (--deal-results-collapse-dx/dy), см. GameTable useLayoutEffect.
 * scale раньше уменьшаем, чтобы к бейджу `.game-info-left-section` подлетал уже «кружок Σ»,
 * а не накрывал весь plasma-экранчик.
 */
@keyframes dealResultsCollapseMobile {
  0% {
    transform: translate(0, 0) scale(1);
    border-radius: 20px;
    opacity: 1;
  }
  42% {
    transform: translate(
        calc(var(--deal-results-collapse-dx, 0px) * 0.42),
        calc(var(--deal-results-collapse-dy, 0px) * 0.42)
      )
      scale(0.14);
    border-radius: 50%;
    opacity: 1;
  }
  100% {
    transform: translate(var(--deal-results-collapse-dx, 0px), var(--deal-results-collapse-dy, 0px))
      scale(0.052);
    border-radius: 50%;
    opacity: 0.9;
  }
}

/* --- Космическая приборная (модалки итогов, рейтинг) --- */
.cosmic-cockpit {
  position: relative;
  isolation: isolate;
  --cc-accent: rgba(139, 92, 246, 0.75);
  --cc-rail: rgba(129, 140, 248, 0.9);
  --cc-text: #e9d5ff;
  --cc-text-dim: #c4b5fd;
  --cc-cyan: #67e8f9;
}
.cosmic-cockpit__content {
  position: relative;
  z-index: 1;
}
.cosmic-cockpit::before {
  content: '';
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  opacity: 0.92;
  background:
    linear-gradient(90deg, var(--cc-rail) 0 11px, transparent) 5px 5px / 11px 1px no-repeat,
    linear-gradient(180deg, var(--cc-rail) 0 11px, transparent) 5px 5px / 1px 11px no-repeat,
    linear-gradient(270deg, var(--cc-rail) 0 11px, transparent) calc(100% - 5px) 5px / 11px 1px no-repeat,
    linear-gradient(180deg, var(--cc-rail) 0 11px, transparent) calc(100% - 5px) 5px / 1px 11px no-repeat,
    linear-gradient(90deg, var(--cc-rail) 0 11px, transparent) 5px calc(100% - 5px) / 11px 1px no-repeat,
    linear-gradient(0deg, var(--cc-rail) 0 11px, transparent) 5px calc(100% - 5px) / 1px 11px no-repeat,
    linear-gradient(270deg, var(--cc-rail) 0 11px, transparent) calc(100% - 5px) calc(100% - 5px) / 11px 1px no-repeat,
    linear-gradient(0deg, var(--cc-rail) 0 11px, transparent) calc(100% - 5px) calc(100% - 5px) / 1px 11px no-repeat,
    radial-gradient(ellipse 120% 80% at 50% -30%, rgba(124, 58, 237, 0.45) 0%, transparent 55%),
    radial-gradient(ellipse 70% 50% at 100% 80%, rgba(34, 211, 238, 0.18) 0%, transparent 50%),
    linear-gradient(168deg, #14082a 0%, #0a1020 45%, #060912 100%);
}
.cosmic-cockpit::after {
  content: '';
  pointer-events: none;
  position: absolute;
  left: 12%;
  right: 12%;
  top: 0;
  height: 1px;
  z-index: 2;
  background: linear-gradient(90deg, transparent, var(--cc-cyan), #e879f9, var(--cc-cyan), transparent);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.55);
  animation: cosmic-cockpit-rail-shimmer 4s ease-in-out infinite;
}
@keyframes cosmic-cockpit-rail-shimmer {
  0%, 100% { opacity: 0.65; }
  50% { opacity: 1; }
}
.cosmic-cockpit__led {
  position: absolute;
  z-index: 3;
  width: 6px;
  height: 6px;
  margin: -3px 0 0 -3px;
  border-radius: 50%;
  box-shadow: 0 0 6px currentColor;
}
.cosmic-cockpit__led--tl { top: 7px; left: 7px; color: #22d3ee; }
.cosmic-cockpit__led--tr { top: 7px; right: 7px; color: #e879f9; }
.cosmic-cockpit__led--bl { bottom: 7px; left: 7px; color: #a78bfa; }
.cosmic-cockpit__led--br { bottom: 7px; right: 7px; color: #f472b6; }
.cosmic-cockpit__orbit {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(167, 139, 250, 0.22);
  pointer-events: none;
  z-index: 0;
  opacity: 0.55;
}
.cosmic-cockpit__orbit--a {
  width: 72px;
  height: 72px;
  top: 8%;
  right: 6%;
  animation: cosmic-orbit-drift 18s linear infinite;
}
.cosmic-cockpit__orbit--b {
  width: 44px;
  height: 44px;
  bottom: 12%;
  left: 8%;
  border-color: rgba(34, 211, 238, 0.25);
  animation: cosmic-orbit-drift 24s linear infinite reverse;
}
@keyframes cosmic-orbit-drift {
  to { transform: rotate(360deg); }
}
.cosmic-cockpit__star {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #f5f3ff;
  box-shadow: 0 0 6px #c4b5fd;
  pointer-events: none;
  z-index: 0;
  animation: cosmic-star-twinkle 3s ease-in-out infinite;
}
.cosmic-cockpit__star--1 { top: 18%; left: 22%; animation-delay: 0s; }
.cosmic-cockpit__star--2 { top: 42%; right: 18%; animation-delay: 1.1s; }
.cosmic-cockpit__star--3 { bottom: 24%; left: 38%; animation-delay: 2s; }
@keyframes cosmic-star-twinkle {
  0%, 100% { opacity: 0.35; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1.15); }
}
.cosmic-iridescent-text {
  background: linear-gradient(
    105deg,
    #fde68a 0%,
    #e879f9 18%,
    #67e8f9 38%,
    #c4b5fd 58%,
    #6ee7b7 78%,
    #fde68a 100%
  );
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: deal-results-user-number-iridescent-shift 12s ease-in-out infinite;
}
.game-over-cloud-status {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 12px;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid rgba(129, 140, 248, 0.45);
  background: rgba(46, 16, 101, 0.55);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.game-over-cloud-status__lamp {
  flex-shrink: 0;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff 0%, var(--lamp) 45%, transparent 100%);
