  border-radius: 0 8px 8px 0;
}
.game-over-table__row--neon-cyan td {
  background: linear-gradient(90deg, rgba(34, 211, 238, 0.18) 0%, rgba(15, 23, 42, 0.35) 100%);
  box-shadow: inset 3px 0 0 #22d3ee, 0 0 16px rgba(34, 211, 238, 0.12);
}
.game-over-table__row--neon-cyan .game-over-table__name {
  color: #67e8f9;
  text-shadow: 0 0 12px rgba(34, 211, 238, 0.45);
}
.game-over-table__row--neon-magenta td {
  background: linear-gradient(90deg, rgba(236, 72, 153, 0.16) 0%, rgba(15, 23, 42, 0.35) 100%);
  box-shadow: inset 3px 0 0 #ec4899, 0 0 16px rgba(236, 72, 153, 0.1);
}
.game-over-table__row--neon-magenta .game-over-table__name {
  color: #f9a8d4;
  text-shadow: 0 0 12px rgba(244, 114, 182, 0.4);
}
.game-over-table__row--neon-amber td {
  background: linear-gradient(90deg, rgba(251, 191, 36, 0.14) 0%, rgba(15, 23, 42, 0.35) 100%);
  box-shadow: inset 3px 0 0 #fbbf24, 0 0 16px rgba(251, 191, 36, 0.1);
}
.game-over-table__row--neon-amber .game-over-table__name {
  color: #fde68a;
  text-shadow: 0 0 12px rgba(251, 191, 36, 0.4);
}
.game-over-table__row--neon-lime td {
  background: linear-gradient(90deg, rgba(163, 230, 53, 0.14) 0%, rgba(15, 23, 42, 0.35) 100%);
  box-shadow: inset 3px 0 0 #a3e635, 0 0 16px rgba(163, 230, 53, 0.1);
}
.game-over-table__row--neon-lime .game-over-table__name {
  color: #bef264;
  text-shadow: 0 0 12px rgba(163, 230, 53, 0.4);
}
.game-over-table__row:hover td {
  filter: brightness(1.12);
  transform: translateX(2px);
  cursor: default;
}
.game-over-table__row--leader td {
  box-shadow: inset 3px 0 0 #fde68a, 0 0 22px rgba(252, 211, 77, 0.15);
}
.game-over-table__rank {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #c4b5fd;
}
.game-over-table__name {
  font-weight: 700;
}
.game-over-table__row--human td {
  outline: 1px solid rgba(34, 211, 238, 0.35);
}
.game-over-table__row--human .game-over-table__name {
  font-weight: 800;
}
.game-over-table__score {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: #a5f3fc;
}
.game-over-table__chips {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.game-over-num--plus { color: #6ee7b7; }
.game-over-num--minus { color: #fca5a5; }

.game-over-expanded-footnote {
  margin: 8px 0 0;
  font-size: 0.82rem;
  color: #a78bfa;
  line-height: 1.45;
}

.game-over-panel {
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid rgba(34, 211, 238, 0.22);
  background: rgba(15, 23, 42, 0.55);
}
.game-over-panel--violet {
  border-color: rgba(167, 139, 250, 0.35);
  background: rgba(46, 16, 101, 0.28);
}
.game-over-panel__title {
  margin: 0 0 10px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #a78bfa;
}
.game-over-accuracy-row {
  display: grid;
  grid-template-columns: minmax(52px, 28%) 1fr 36px;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
  font-size: 0.82rem;
}
.game-over-accuracy-row__name {
  color: #ddd6fe;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.game-over-accuracy-row__name--human {
  color: #67e8f9;
  font-weight: 600;
}
.game-over-accuracy-row__track {
  height: 7px;
  border-radius: 4px;
  background: rgba(30, 27, 75, 0.5);
  border: 1px solid rgba(129, 140, 248, 0.35);
  overflow: hidden;
}
.game-over-accuracy-row__fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, rgba(99, 102, 241, 0.85), rgba(139, 92, 246, 0.9));
  transition: width 0.35s ease;
}
.game-over-accuracy-row__fill--best {
  background: linear-gradient(90deg, rgba(34, 211, 238, 0.65), rgba(139, 92, 246, 0.95));
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.35);
}
.game-over-accuracy-row__pct {
  text-align: right;
  color: #e9d5ff;
  font-variant-numeric: tabular-nums;
}
.game-over-kv {
  margin: 0;
  display: grid;
  gap: 6px;
  font-size: 0.82rem;
}
.game-over-kv > div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.game-over-kv dt {
  margin: 0;
  color: #c4b5fd;
}
.game-over-kv dd {
  margin: 0;
  color: #ecfeff;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.game-over-expanded-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.game-over-btn {
  font: inherit;
  font-size: 0.85rem;
  font-weight: 600;
  padding: 10px 16px;
  border-radius: 10px;
  cursor: pointer;
  touch-action: manipulation;
  transition: filter 0.15s, box-shadow 0.15s;
}
.game-over-btn--primary {
  border: 1px solid rgba(34, 211, 238, 0.65);
  color: #a5f3fc;
  background: linear-gradient(180deg, rgba(34, 211, 238, 0.22) 0%, rgba(21, 94, 117, 0.35) 100%);
  box-shadow: 0 0 16px rgba(34, 211, 238, 0.25);
}
.game-over-btn--secondary {
  border: 1px solid rgba(148, 163, 184, 0.35);
  color: #cbd5e1;
  background: rgba(15, 23, 42, 0.65);
}
.game-over-btn:hover {
  filter: brightness(1.12);
}

.game-over-lk-link {
  color: #67e8f9;
  font-weight: 700;
  text-decoration: none;
  border-bottom: 1px solid rgba(103, 232, 249, 0.45);
  text-shadow: 0 0 10px rgba(34, 211, 238, 0.45);
}
.game-over-lk-link:hover {
  color: #ecfeff;
  border-bottom-color: #a5f3fc;
}
.game-over-cloud-status__sub {
  display: block;
  margin-top: 2px;
  font-size: 0.76rem;
  font-weight: 500;
  color: #c4b5fd;
}

/* Дашборды мостика: крутилки, диоды, точность */
.bridge-dash,
.bridge-accuracy {
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(129, 140, 248, 0.4);
  background: linear-gradient(160deg, rgba(30, 27, 75, 0.75) 0%, rgba(8, 12, 28, 0.9) 100%);
  box-shadow: inset 0 0 28px rgba(124, 58, 237, 0.12), 0 0 20px rgba(34, 211, 238, 0.08);
}
.bridge-dash--interactive:hover,
.bridge-accuracy--interactive:hover {
  border-color: rgba(103, 232, 249, 0.55);
  box-shadow: inset 0 0 32px rgba(124, 58, 237, 0.18), 0 0 28px rgba(34, 211, 238, 0.15);
}
.bridge-dash__header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}
.bridge-dash__header-text {
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #e9d5ff;
  text-shadow: 0 0 10px rgba(167, 139, 250, 0.45);
}
.bridge-dash__header-led {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #64748b;
  box-shadow: 0 0 6px rgba(100, 116, 139, 0.5);
}
.bridge-dash__header-led--pulse {
  background: #67e8f9;
  box-shadow: 0 0 12px rgba(34, 211, 238, 0.7);
  animation: bridge-led-blink 1.6s ease-in-out infinite;
}
.bridge-dash__gauges {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 14px;
  margin-bottom: 12px;
}
.bridge-gauge {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 6px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px solid rgba(99, 102, 241, 0.25);
  transition: transform 0.15s, box-shadow 0.2s;
}
.bridge-gauge:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}
.bridge-gauge__led {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #475569;
  opacity: 0.6;
}
.bridge-gauge__led--on {
  opacity: 1;
  animation: bridge-led-blink 2s ease-in-out infinite;
}
.bridge-gauge--cyan .bridge-gauge__led--on {
  background: #22d3ee;
  box-shadow: 0 0 10px #22d3ee;
}
.bridge-gauge--magenta .bridge-gauge__led--on {
  background: #ec4899;
  box-shadow: 0 0 10px #ec4899;
}
.bridge-gauge--amber .bridge-gauge__led--on {
  background: #fbbf24;
  box-shadow: 0 0 10px #fbbf24;
}
.bridge-gauge--lime .bridge-gauge__led--on {
  background: #a3e635;
  box-shadow: 0 0 10px #a3e635;
}
.bridge-gauge--violet .bridge-gauge__led--on {
  background: #a78bfa;
  box-shadow: 0 0 10px #a78bfa;
}
.bridge-gauge__dial {
  position: relative;
  width: 52px;
  height: 52px;
  --gauge-pct: 0;
  --gauge-rot: -90deg;
  flex-shrink: 0;
}
.bridge-gauge__ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(
    from -90deg,
    color-mix(in srgb, var(--gauge-fill, #67e8f9) 75%, transparent) 0deg,
    color-mix(in srgb, var(--gauge-fill, #67e8f9) 75%, transparent) calc(var(--gauge-pct) * 2.7deg),
    rgba(51, 65, 85, 0.45) calc(var(--gauge-pct) * 2.7deg),
    rgba(51, 65, 85, 0.45) 270deg,
    transparent 270deg
  );
  mask: radial-gradient(circle, transparent 62%, #000 63%);
  -webkit-mask: radial-gradient(circle, transparent 62%, #000 63%);
}
.bridge-gauge--cyan { --gauge-fill: #22d3ee; }
.bridge-gauge--magenta { --gauge-fill: #ec4899; }
.bridge-gauge--amber { --gauge-fill: #fbbf24; }
.bridge-gauge--lime { --gauge-fill: #a3e635; }
.bridge-gauge--violet { --gauge-fill: #a78bfa; }
.bridge-gauge__needle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2px;
  height: 20px;
  margin-left: -1px;
  margin-top: -19px;
  transform-origin: 50% 100%;
  transform: rotate(var(--gauge-rot));
  background: linear-gradient(180deg, #fef9c3, #d97706);
  border-radius: 1px;
  box-shadow: 0 0 4px rgba(251, 191, 36, 0.45);
  transition: transform 0.5s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.bridge-gauge__readout {
  font-size: 1.05rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #ecfeff;
  line-height: 1.1;
  letter-spacing: 0.02em;
}
.bridge-gauge__label {
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #a78bfa;
}
.bridge-gauge__detail {
  font-size: 0.62rem;
  font-weight: 500;
  color: #c4b5fd;
  text-align: center;
  line-height: 1.2;
  max-width: 100%;
}
.bridge-dash__strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  padding-top: 10px;
  border-top: 1px solid rgba(129, 140, 248, 0.3);
}
.bridge-dash__strip-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #a78bfa;
}
.bridge-dash__diodes {
  display: flex;
  gap: 6px;
  flex: 1;
}
.bridge-dash__diode {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  background: rgba(51, 65, 85, 0.8);
  border: 1px solid rgba(71, 85, 105, 0.8);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.45);
}
.bridge-dash__diode--on {
  background: linear-gradient(180deg, #6ee7b7 0%, #059669 100%);
  border-color: rgba(52, 211, 153, 0.7);
  box-shadow: 0 0 12px rgba(52, 211, 153, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.35);
  animation: bridge-diode-flash 2.5s ease-in-out infinite;
}
@keyframes bridge-diode-flash {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.75; }
}
.bridge-dash__strip-value {
  font-size: 0.88rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #6ee7b7;
  text-shadow: 0 0 10px rgba(52, 211, 153, 0.4);
}
.bridge-accuracy__row {
  display: grid;
  grid-template-columns: 12px minmax(48px, 26%) 1fr 42px;
  align-items: center;
  gap: 8px;
  margin-bottom: 9px;
  padding: 6px 8px;
  border-radius: 8px;
  transition: background 0.2s, box-shadow 0.2s;
}
.bridge-accuracy__row:hover {
  background: rgba(99, 102, 241, 0.12);
}
.bridge-accuracy__row--peak {
  box-shadow: 0 0 14px rgba(252, 211, 77, 0.2);
}
.bridge-accuracy__led {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #475569;
}
.bridge-accuracy__row--cyan .bridge-accuracy__led { background: #22d3ee; box-shadow: 0 0 8px #22d3ee; }
.bridge-accuracy__row--magenta .bridge-accuracy__led { background: #ec4899; box-shadow: 0 0 8px #ec4899; }
.bridge-accuracy__row--amber .bridge-accuracy__led { background: #fbbf24; box-shadow: 0 0 8px #fbbf24; }
.bridge-accuracy__row--lime .bridge-accuracy__led { background: #a3e635; box-shadow: 0 0 8px #a3e635; }
.bridge-accuracy__name {
  font-size: 0.88rem;
  font-weight: 700;
  color: #e9d5ff;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.bridge-accuracy__row--human .bridge-accuracy__name {
  color: #67e8f9;
  text-shadow: 0 0 10px rgba(34, 211, 238, 0.35);
}
.bridge-accuracy__meter {
  position: relative;
  height: 10px;
  border-radius: 5px;
  background: rgba(30, 27, 75, 0.65);
  border: 1px solid rgba(99, 102, 241, 0.35);
  overflow: hidden;
}
.bridge-accuracy__row--cyan .bridge-accuracy__fill {
  background: linear-gradient(90deg, rgba(34, 211, 238, 0.5), #22d3ee);
  box-shadow: 0 0 12px rgba(34, 211, 238, 0.45);
}
.bridge-accuracy__row--magenta .bridge-accuracy__fill {
  background: linear-gradient(90deg, rgba(236, 72, 153, 0.5), #ec4899);
  box-shadow: 0 0 12px rgba(236, 72, 153, 0.4);
}
.bridge-accuracy__row--amber .bridge-accuracy__fill {
  background: linear-gradient(90deg, rgba(251, 191, 36, 0.5), #fbbf24);
  box-shadow: 0 0 12px rgba(251, 191, 36, 0.4);
}
.bridge-accuracy__row--lime .bridge-accuracy__fill {
  background: linear-gradient(90deg, rgba(163, 230, 53, 0.5), #a3e635);
  box-shadow: 0 0 12px rgba(163, 230, 53, 0.4);
}
.bridge-accuracy__fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.45s cubic-bezier(0.34, 1.1, 0.64, 1);
}
.bridge-accuracy__spark {
  position: absolute;
  right: 0;
  top: 0;
  width: 6px;
  height: 100%;
  background: rgba(255, 255, 255, 0.55);
  filter: blur(2px);
  opacity: 0;
  animation: bridge-meter-spark 2.8s ease-in-out infinite;
}
.bridge-accuracy__row--peak .bridge-accuracy__spark {
  opacity: 0.85;
}
@keyframes bridge-meter-spark {
  0%, 70%, 100% { opacity: 0; transform: translateX(0); }
  85% { opacity: 0.9; transform: translateX(-4px); }
}
.bridge-accuracy__pct {
  font-size: 0.88rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: #ecfeff;
}

/* --- Мостик корабля: итоги партии --- */
.game-over-bridge {
  position: relative;
  min-height: 0;
  overflow: hidden;
}
.game-over-bridge__body-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.game-over-bridge__body {
  flex: 1;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.game-over-bridge__scenery {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.game-over-bridge__galaxy {
  position: absolute;
  inset: -20%;
  background:
    radial-gradient(ellipse 55% 40% at 72% 28%, rgba(88, 28, 135, 0.55) 0%, transparent 55%),
    radial-gradient(ellipse 45% 35% at 18% 72%, rgba(14, 116, 144, 0.35) 0%, transparent 50%),
    radial-gradient(ellipse 80% 50% at 50% 100%, rgba(30, 27, 75, 0.65) 0%, transparent 60%);
  opacity: 0.85;
  animation: bridge-galaxy-drift 28s ease-in-out infinite alternate;
}
@keyframes bridge-galaxy-drift {
  0% { transform: scale(1) rotate(0deg); }
  100% { transform: scale(1.06) rotate(2deg); }
}
.game-over-bridge__saturn {
  position: absolute;
  right: 4%;
  top: 18%;
  width: 88px;
  height: 88px;
}
.game-over-bridge__saturn-core {
  position: absolute;
  inset: 22%;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fde68a 0%, #c084fc 40%, #4c1d95 100%);
  box-shadow: 0 0 24px rgba(192, 132, 252, 0.5);
}
.game-over-bridge__saturn-ring {
  position: absolute;
  inset: 8% 0;
  border-radius: 50%;
  border: 3px solid rgba(167, 139, 250, 0.45);
  transform: rotateX(68deg);
  box-shadow: 0 0 18px rgba(34, 211, 238, 0.25);
}
.game-over-bridge__comet {
  position: absolute;
  left: -8%;
  top: 8%;
  width: 140px;
  height: 3px;
  background: linear-gradient(90deg, transparent, rgba(103, 232, 249, 0.9), transparent);
  transform: rotate(-18deg);
  filter: blur(0.5px);
  animation: bridge-comet-pass 9s ease-in-out infinite;
}
@keyframes bridge-comet-pass {
  0%, 70% { opacity: 0; transform: translate(0, 0) rotate(-18deg); }
  85% { opacity: 1; }
  100% { opacity: 0; transform: translate(280px, 120px) rotate(-18deg); }
}
.game-over-bridge__planet {
  position: absolute;
  border-radius: 50%;
  box-shadow: inset -4px -4px 12px rgba(0, 0, 0, 0.45);
}
.game-over-bridge__planet--a {
  width: 22px;
  height: 22px;
  left: 12%;
  bottom: 22%;
  background: radial-gradient(circle at 30% 28%, #67e8f9, #1e3a8a);
}
.game-over-bridge__planet--b {
  width: 14px;
  height: 14px;
  right: 28%;
  bottom: 12%;
  background: radial-gradient(circle at 30% 28%, #f9a8d4, #7e22ce);
}
.game-over-bridge__scanlines {
  position: absolute;
  inset: 0;
  opacity: 0.06;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.5) 2px,
    rgba(255, 255, 255, 0.5) 3px
  );
}
.game-over-bridge__hud {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  max-height: min(86dvh, 88vh);
}
/* ПК/планшет (без mobile-chrome): hud заполняет мост, иначе body не получает высоту и скролл мёртв */
.game-over-root--expanded.game-over-bridge > .game-over-bridge__hud {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}
.game-over-bridge__grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
}
.game-over-bridge__main-col {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}
.game-over-bridge__telemetry {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}
.game-over-panel--telemetry {
  flex: 1;
}

.bridge-chip-reel {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px 14px;
  padding: 10px 14px 10px 16px;
  border-radius: 12px;
  border: 1px solid rgba(34, 211, 238, 0.4);
  background: linear-gradient(135deg, rgba(6, 78, 59, 0.35) 0%, rgba(46, 16, 101, 0.55) 55%, rgba(15, 23, 42, 0.8) 100%);
  box-shadow: inset 0 0 20px rgba(34, 211, 238, 0.12), 0 0 20px rgba(124, 58, 237, 0.2);
  overflow: hidden;
}
.bridge-chip-reel--minus {
  border-color: rgba(248, 113, 113, 0.45);
  background: linear-gradient(135deg, rgba(69, 10, 10, 0.4) 0%, rgba(46, 16, 101, 0.5) 100%);
}
.bridge-chip-reel__tag {
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #c4b5fd;
}
.bridge-chip-reel__value {
  font-size: 2rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(92deg, #6ee7b7, #67e8f9, #e9d5ff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
