.bridge-viewport__corner--tl { top: 0; left: 0; border-right: none; border-bottom: none; }
.bridge-viewport__corner--tr { top: 0; right: 0; border-left: none; border-bottom: none; }
.bridge-viewport__corner--bl { bottom: 0; left: 0; border-right: none; border-top: none; }
.bridge-viewport__corner--br { bottom: 0; right: 0; border-left: none; border-top: none; }
.bridge-viewport__scan {
