.bridge-dock {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1.15fr 1.01fr;
  gap: 8px;
  margin-top: auto;
  padding-top: 8px;
  border-top: none;
  flex-shrink: 0;
}
.bridge-dock::before {
  content: '';
  position: absolute;
  top: 0;
  left: 3%;
  right: 3%;
  height: 2.5px;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(103, 232, 249, 0.45) 10%,
    rgba(196, 181, 253, 0.92) 28%,
    rgba(34, 211, 238, 1) 50%,
    rgba(196, 181, 253, 0.92) 72%,
    rgba(103, 232, 249, 0.45) 90%,
    transparent 100%
  );
  box-shadow:
    0 0 12px rgba(34, 211, 238, 0.62),
    0 0 26px rgba(167, 139, 250, 0.38),
    0 1px 0 rgba(255, 255, 255, 0.22);
  pointer-events: none;
}
.bridge-dock::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 14%;
  right: 14%;
  height: 1px;
  border-radius: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(236, 254, 255, 0.28) 35%,
    rgba(34, 211, 238, 0.42) 50%,
    rgba(236, 254, 255, 0.28) 65%,
    transparent 100%
  );
  pointer-events: none;
}
.bridge-pod {
  position: relative;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 0;
  padding: 4px 11px;
  border: 1px solid rgba(167, 139, 250, 0.38);
  border-radius: 11px;
  cursor: pointer;
  font: inherit;
  touch-action: manipulation;
  color: inherit;
  overflow: hidden;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  background: linear-gradient(
    148deg,
    rgba(76, 29, 149, 0.42) 0%,
    rgba(30, 27, 75, 0.78) 42%,
    rgba(15, 23, 42, 0.88) 100%
  );
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.16),
    inset 0 -2px 0 rgba(0, 0, 0, 0.26),
    0 3px 0 rgba(10, 5, 24, 0.52),
    0 5px 14px rgba(0, 0, 0, 0.28),
    0 0 20px rgba(124, 58, 237, 0.14);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.12s;
}
.bridge-pod::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(ellipse 90% 70% at 50% -20%, rgba(167, 139, 250, 0.22), transparent 62%);
  pointer-events: none;
  opacity: 0.85;
}
.bridge-pod__shine {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    118deg,
    transparent 0%,
    rgba(255, 255, 255, 0.1) 44%,
    transparent 58%
  );
  pointer-events: none;
}
.bridge-pod:hover,
.bridge-pod:focus-visible {
  border-color: rgba(103, 232, 249, 0.5);
  transform: translateY(-1px);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.22),
    inset 0 -2px 0 rgba(0, 0, 0, 0.22),
    0 4px 0 rgba(10, 5, 24, 0.5),
    0 0 26px rgba(34, 211, 238, 0.24),
    0 8px 20px rgba(0, 0, 0, 0.34);
}
.bridge-pod:hover::before,
.bridge-pod:focus-visible::before {
  opacity: 1;
}
.bridge-pod:active {
  transform: translateY(1px) scale(0.985);
  box-shadow:
    inset 0 2px 6px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 1px 0 rgba(10, 5, 24, 0.45),
    0 2px 8px rgba(0, 0, 0, 0.22);
}
.bridge-pod__icon {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.72rem;
  height: 1.72rem;
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1;
  border-radius: 8px;
  color: #67e8f9;
  background: linear-gradient(
    165deg,
    rgba(255, 255, 255, 0.3) 0%,
    rgba(147, 130, 255, 0.3) 40%,
    rgba(30, 27, 75, 0.58) 100%
  );
  border: 1px solid rgba(196, 181, 253, 0.42);
  box-shadow:
    inset 0 2px 4px rgba(255, 255, 255, 0.3),
    inset 0 -3px 5px rgba(0, 0, 0, 0.38),
    0 3px 8px rgba(0, 0, 0, 0.32),
    0 0 14px rgba(34, 211, 238, 0.2);
  text-shadow:
    0 1px 0 rgba(255, 255, 255, 0.42),
    0 -1px 0 rgba(0, 0, 0, 0.32),
    0 0 10px rgba(34, 211, 238, 0.45);
  transition: box-shadow 0.15s, transform 0.12s;
}
.bridge-pod:hover .bridge-pod__icon,
.bridge-pod:focus-visible .bridge-pod__icon {
  transform: translateY(-1px);
  box-shadow:
    inset 0 2px 5px rgba(255, 255, 255, 0.34),
    inset 0 -3px 5px rgba(0, 0, 0, 0.34),
    0 4px 10px rgba(0, 0, 0, 0.36),
    0 0 16px rgba(34, 211, 238, 0.28);
}
.bridge-pod:active .bridge-pod__icon {
  transform: translateY(1px);
  box-shadow:
    inset 0 3px 6px rgba(0, 0, 0, 0.42),
