.lk-page {
  --lk-font-display: 'Orbitron', 'Exo 2', ui-sans-serif, system-ui, sans-serif;
  --lk-font-ui: 'Exo 2', 'Outfit', ui-sans-serif, system-ui, sans-serif;
  --lk-font-mono: 'Share Tech Mono', 'JetBrains Mono', ui-monospace, monospace;
  --lk-sheen: linear-gradient(
    105deg,
    #67e8f9 0%,
    #22d3ee 16%,
    #a78bfa 38%,
    #e879f9 55%,
    #f472b6 72%,
    #fcd34d 100%
  );
  --lk-ink: #d8b4fe;
  --lk-ink-strong: #f5e1ff;
  --lk-cyan: #67e8f9;
  --lk-mint: #5eead4;
  position: fixed;
  inset: 0;
  z-index: 110;
  box-sizing: border-box;
  min-height: 100%;
  min-height: 100dvh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding:
    max(16px, env(safe-area-inset-top, 0px))
    max(16px, env(safe-area-inset-right, 0px))
    max(16px, env(safe-area-inset-bottom, 0px))
    max(16px, env(safe-area-inset-left, 0px));
  overflow-x: clip;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background: #050510;
  font-family: var(--lk-font-ui);
  color: var(--lk-ink);
}
