.deal-results-btn {
  animation: dealResultsButtonPop 0.4s ease-out, dealResultsButtonBlink 2.8s ease-in-out 0.6s 2;
}

.deal-results-btn:hover {
  animation: none;
}

.deal-results-btn::after {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 50%;
  background: linear-gradient(
    105deg,
    transparent 0%,
    transparent 35%,
    rgba(255, 255, 255, 0.45) 50%,
    transparent 65%,
    transparent 100%
  );
  background-size: 200% 100%;
  background-position: -100% 0;
  pointer-events: none;
  opacity: 0;
}

.deal-results-btn:hover::after {
  opacity: 1;
  animation: dealResultsBtnShimmer 0.5s ease-out forwards;
}

@keyframes dealResultsBtnShimmer {
  0% {
    background-position: -100% 0;
    opacity: 1;
  }
  100% {
    background-position: 100% 0;
    opacity: 1;
  }
}

@keyframes bidPanelSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
