}

/* --- Лаборатория шкалы раздач `/deal-track-lab` (dev): 28 раздач, подписи как у таблицы результатов --- */
.deal-track-lab {
  /* Подсветка зоны текущей раздачи (фон под шариком), не сам шарик */
  --deal-lab-section-active-bg: rgb(218 49 130 / 70%);
  /* Дублируется из TSX на `<main>` — запасной размер шариков */
  --deal-lab-point-size: 26px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 50% -20%, rgba(34, 211, 238, 0.14) 0%, transparent 42%),
    radial-gradient(circle at 84% 18%, rgba(167, 139, 250, 0.16) 0%, transparent 44%),
    radial-gradient(circle at 14% 68%, rgba(99, 102, 241, 0.12) 0%, transparent 38%),
    linear-gradient(165deg, #0f172a 0%, #020617 55%, #010409 100%);
  color: #e2e8f0;
  padding: clamp(16px, 3vw, 28px);
}
.deal-track-lab-inner {
  max-width: 1240px;
  margin: 0 auto;
}
.deal-track-lab-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.deal-track-lab-title {
  margin: 0 0 6px;
  font-size: clamp(1.15rem, 2.2vw, 1.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #e0f2fe 0%, #bae6fd 40%, #c4b5fd 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.deal-track-lab-sub {
  margin: 0;
  font-size: 13px;
  color: rgba(148, 163, 184, 0.95);
  max-width: 52ch;
  line-height: 1.45;
}
.deal-track-lab-back {
  flex-shrink: 0;
  border-radius: 10px;
  border: 1px solid rgba(71, 85, 105, 0.85);
  background: rgba(30, 41, 59, 0.75);
  color: #e2e8f0;
  padding: 10px 16px;
  cursor: pointer;
  font-weight: 600;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.06) inset,
    0 12px 32px rgba(0, 0, 0, 0.35);
  transition:
    transform 0.14s ease,
    border-color 0.14s ease,
    background 0.14s ease;
}
@media (hover: hover) and (pointer: fine) {
  .deal-track-lab-back:hover {
    transform: translateY(-1px);
    border-color: rgba(148, 163, 184, 0.55);
    background: rgba(51, 65, 85, 0.9);
  }
}
.deal-track-lab-panel {
  border: 1px solid rgba(71, 85, 105, 0.7);
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(10px);
  border-radius: 14px;
  padding: 16px 18px;
  margin-bottom: 18px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.05) inset,
    0 18px 48px rgba(2, 6, 23, 0.55);
}
.deal-track-lab-panel-text {
  font-size: 14px;
  color: #cbd5e1;
  margin-bottom: 12px;
  line-height: 1.4;
}
.deal-track-lab-accent {
  color: #22d3ee;
  font-weight: 800;
}
.deal-track-lab-panel-hint {
  color: rgba(148, 163, 184, 0.95);
  font-weight: 500;
}

.deal-track-lab-range {
  width: 100%;
  height: 8px;
  border-radius: 999px;
  appearance: none;
  background: linear-gradient(
    90deg,
    rgba(51, 65, 85, 0.9) 0%,
    rgba(30, 41, 59, 0.95) 100%
  );
  outline: none;
  box-shadow: 0 0 0 1px rgba(148, 163, 184, 0.12) inset;
}
.deal-track-lab-range::-webkit-slider-thumb {
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #e0f2fe 0%, #22d3ee 45%, #0369a1 100%);
  border: 1px solid rgba(226, 232, 240, 0.45);
  box-shadow:
    0 0 0 6px rgba(34, 211, 238, 0.2),
    0 12px 24px rgba(8, 47, 73, 0.55);
  cursor: grab;
}
.deal-track-lab-range:active::-webkit-slider-thumb {
  cursor: grabbing;
}
.deal-track-lab-range::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #e0f2fe 0%, #22d3ee 45%, #0369a1 100%);
  border: 1px solid rgba(226, 232, 240, 0.45);
  box-shadow:
    0 0 0 6px rgba(34, 211, 238, 0.2),
    0 12px 24px rgba(8, 47, 73, 0.55);
  cursor: grab;
}

.deal-track-lab-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(280px, 1fr));
  gap: 16px;
  align-items: start;
}
@media (max-width: 1100px) {
  .deal-track-lab-grid {
    grid-template-columns: 1fr;
  }
}
.deal-track-lab-card--wide {
  grid-column: 1 / -1;
}
.deal-track-lab-card {
  border: 1px solid rgba(71, 85, 105, 0.65);
  background: linear-gradient(160deg, rgba(15, 23, 42, 0.7) 0%, rgba(30, 27, 75, 0.35) 100%);
  backdrop-filter: blur(12px);
  border-radius: 14px;
  padding: 16px;
  min-height: 420px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.04) inset,
    0 22px 50px rgba(2, 6, 23, 0.45);
}
.deal-track-lab-h2 {
  margin: 0 0 8px;
  font-size: 15px;
  font-weight: 750;
  color: #f1f5f9;
  letter-spacing: -0.01em;
}
.deal-track-lab-card-lead {
  margin: 0 0 12px;
  font-size: 12px;
  color: rgba(148, 163, 184, 0.95);
  line-height: 1.35;
}

/*
 * общие точки: «ячейка» в материале (вмятина) + шар утоплен внутрь —
 * тёмное скругление сверху, лёгкий изгиб подсветки снизу, контактная тень.
 */
.deal-track-lab-point {
  width: var(--deal-lab-point-size, 26px);
  height: var(--deal-lab-point-size, 26px);
  border-radius: 50%;
  flex-shrink: 0;
  border: 1px solid rgba(226, 232, 240, 0.32);
  box-sizing: border-box;
  isolation: isolate;
  /* Переменная задаётся по номеру раздачи из TSX */
  --deal-hue: 220;
  /* активный шар визуально крупнее базы (явный calc — иначе scale 1.1 на 26px почти не виден) */
  --deal-lab-point-active-mult: 1.36;
  /* ямка — глубина без серой «крышки»: тени светлее, чуть больше блику снизу */
  --deal-crater-inner:
    inset 0 8px 15px rgb(15 23 42 / 0.34),
    inset 0 -4px 10px rgb(255 255 255 / 0.095),
    inset 0 -1px 3px rgb(186 206 229 / 0.16),
    inset 0 0 0 1px rgb(30 41 59 / 0.78);
  --deal-crater-outer:
    0 1px 0 rgb(255 255 255 / 0.07),
    0 3px 7px rgb(2 6 23 / 0.38),
    0 5px 11px rgb(2 6 23 / 0.16);
}
/*
 * активный: бирюза в контуре и ореоле фиксированная (hue раздачи к концу партии «уходит»
 * в индиго — без этого подсветка блекнет); тело светлее, низ без тяжёлой серой массы.
 */
.deal-track-lab-point--active {
  --deal-crater-inner:
    inset 0 5px 10px rgb(15 23 42 / 0.2),
    inset 0 -3px 8px rgb(255 255 255 / 0.12),
    inset 0 -1px 2px rgb(165 243 252 / 0.22),
    inset 0 0 0 1px rgb(45 212 191 / 0.28);
  width: calc(var(--deal-lab-point-size, 26px) * var(--deal-lab-point-active-mult));
  height: calc(var(--deal-lab-point-size, 26px) * var(--deal-lab-point-active-mult));
  border-width: 2px;
  border-style: solid;
  border-color: rgb(94 234 212 / 0.98);
  background:
    radial-gradient(ellipse 115% 90% at 50% -10%, rgb(255 255 255 / 0.38) 0%, transparent 42%),
    radial-gradient(circle at 34% 26%, rgb(255 255 255 / 1) 0%, rgb(204 251 241 / 0.55) 14%, transparent 38%),
    radial-gradient(ellipse 90% 70% at 50% 108%, rgb(45 212 191 / 0.22) 0%, transparent 48%),
    conic-gradient(
      from 210deg at 50% 52%,
      hsl(calc(var(--deal-hue) - 16) 98% 74%) 0deg,
      hsl(var(--deal-hue) 97% 71%) 122deg,
      hsl(calc(var(--deal-hue) + 18) 94% 70%) 248deg,
      hsl(calc(var(--deal-hue) - 16) 98% 74%) 360deg
    ),
    radial-gradient(circle at 56% 82%, hsl(var(--deal-hue) 65% 38% / 0.22) 0%, rgb(15 23 42 / 0.22) 62%);
  box-shadow:
    var(--deal-crater-inner),
    var(--deal-crater-outer),
    /* бирюза: кольца у обода, не перебивают сирень дальше */
    0 0 0 1px rgb(103 232 207 / 0.42),
    0 0 0 3px rgb(34 211 238 / 0.26),
    0 0 0 6px rgb(45 212 191 / 0.14),
    /*
     * сирень ближе к шару (до широкого циана) — те же порядки яркости, что у бирюзы у обода.
     */
    0 0 5px rgb(221 214 254 / 0.95),
    0 0 9px rgb(196 181 253 / 0.92),
    0 0 14px rgb(167 139 250 / 0.85),
    0 0 20px rgb(192 169 246 / 0.72),
    /* бирюзовая дымка снаружи — приглушена, чтобы лиловый не тонул */
    0 0 12px rgb(34 211 238 / 0.42),
    0 0 22px rgb(56 189 248 / 0.28),
    0 0 34px rgb(45 212 191 / 0.18),
    /* сирень наружное кольцо — всё ещё ярче фона, но уже «ореол», не конкурирует с цианом у края */
    0 0 28px rgb(167 139 250 / 0.55),
    0 0 44px rgb(139 92 246 / 0.38),
    0 0 38px hsl(var(--deal-hue) 92% 62% / 0.16);
  position: relative;
  z-index: 1;
}
.deal-track-lab-point--future {
  background:
    radial-gradient(ellipse 120% 88% at 50% -6%, rgb(255 255 255 / 0.14) 0%, transparent 44%),
    radial-gradient(circle at 34% 28%, rgb(255 255 255 / 0.55) 0%, transparent 40%),
    conic-gradient(
      from 210deg at 50% 52%,
      hsl(calc(var(--deal-hue) - 10) 52% 44%) 0deg,
      hsl(var(--deal-hue) 54% 40%) 140deg,
      hsl(calc(var(--deal-hue) + 14) 56% 36%) 270deg,
      hsl(calc(var(--deal-hue) - 10) 52% 44%) 360deg
    );
  border-color: hsl(var(--deal-hue) 60% 68% / 0.55);
  box-shadow:
    var(--deal-crater-inner),
    var(--deal-crater-outer);
  opacity: 0.98;
}
.deal-track-lab-point--done.deal-track-lab-point--norm {
