    conic-gradient(
      from 210deg at 50% 52%,
      hsl(calc(var(--deal-hue) - 12) 84% 58%) 0deg,
      hsl(var(--deal-hue) 86% 54%) 140deg,
      hsl(calc(var(--deal-hue) + 14) 80% 50%) 270deg,
      hsl(calc(var(--deal-hue) - 12) 84% 58%) 360deg
    ),
    radial-gradient(circle at 58% 78%, hsl(var(--deal-hue) 70% 28% / 0.35) 0%, transparent 58%);
  border-width: 2px;
  border-style: solid;
  border-color: rgb(94 234 212 / 0.98);
  box-shadow:
    var(--deal-crater-inner),
    var(--deal-crater-outer),
    0 0 0 1px rgb(103 232 207 / 0.42),
    0 0 0 3px rgb(34 211 238 / 0.26),
    0 0 18px rgb(34 211 238 / 0.32),
    0 0 5px rgb(221 214 254 / 0.88),
    0 0 10px rgb(196 181 253 / 0.82),
    0 0 16px rgb(167 139 250 / 0.72),
    0 0 24px rgb(192 169 246 / 0.48),
    0 0 14px rgb(34 211 238 / 0.26),
    0 0 28px rgb(56 189 248 / 0.18),
    0 0 22px rgb(167 139 250 / 0.42),
    0 0 38px rgb(139 92 246 / 0.28);
}
.deal-track-lab-point--done.deal-track-lab-point--nt {
