    radial-gradient(circle at 34% 24%, rgb(236 254 255 / 0.95) 0%, transparent 38%),
    conic-gradient(
      from 220deg at 50% 52%,
      hsl(calc(var(--deal-hue) - 18) 100% 68%) 0deg,
      hsl(var(--deal-hue) 100% 64%) 130deg,
