      hsl(calc(var(--deal-hue) - 18) 100% 68%) 360deg
    );
  border-width: 2px;
  border-style: solid;
  border-color: rgb(94 234 212 / 0.98);
  box-shadow:
    var(--deal-crater-inner),
    var(--deal-crater-outer),
    0 0 0 1px rgb(103 232 207 / 0.42),
    0 0 0 3px rgb(34 211 238 / 0.26),
    0 0 22px rgb(34 211 238 / 0.34),
    0 0 5px rgb(221 214 254 / 0.9),
    0 0 10px rgb(196 181 253 / 0.84),
    0 0 16px rgb(167 139 250 / 0.76),
    0 0 26px rgb(192 169 246 / 0.52),
    0 0 16px rgb(34 211 238 / 0.28),
    0 0 30px rgb(56 189 248 / 0.2),
