  border-style: solid;
  border-color: rgb(94 234 212 / 0.98);
  box-shadow:
    var(--deal-crater-inner),
    var(--deal-crater-outer),
    0 0 0 1px rgb(103 232 207 / 0.42),
    0 0 0 3px rgb(34 211 238 / 0.26),
    0 0 22px rgb(34 211 238 / 0.34),
    0 0 5px rgb(221 214 254 / 0.9),
    0 0 10px rgb(196 181 253 / 0.84),
    0 0 16px rgb(167 139 250 / 0.76),
    0 0 26px rgb(192 169 246 / 0.52),
    0 0 16px rgb(34 211 238 / 0.28),
    0 0 30px rgb(56 189 248 / 0.2),
    0 0 26px rgb(167 139 250 / 0.45),
    0 0 42px rgb(139 92 246 / 0.32);
}

/* A: вертикаль */
.deal-track-lab-vertical {
  position: relative;
  padding-left: 28px;
  max-height: min(60vh, 560px);
  overflow: auto;
  padding-right: 4px;
  scrollbar-color: rgba(100, 116, 139, 0.7) rgba(15, 23, 42, 0.5);
  scrollbar-width: thin;
}
.deal-track-lab-vertical-rail {
  position: absolute;
  left: 17px;
  top: 2px;
  bottom: 2px;
  width: 2px;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    rgba(34, 211, 238, 0.42) 0%,
    rgba(129, 140, 248, 0.36) 55%,
    rgba(167, 139, 250, 0.38) 100%
  );
  box-shadow: 0 0 18px rgba(129, 140, 248, 0.2);
}
.deal-track-lab-row {
  display: grid;
  grid-template-columns: 18px 1fr auto 18px;
  align-items: center;
  gap: 3px;
  width: min(100%, 318px);
  margin-bottom: 0;
  padding: 0 5px;
  border-radius: 8px;
  border: 1px solid transparent;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
  cursor: pointer;
  position: relative;
  isolation: isolate;
  --deal-row-hue: 210;
}

/* Цветное «освещение» панели строки от своего шарика (пер-строка hue из TS). */
.deal-track-lab-row::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  z-index: -1;
  opacity: 0;
  background:
    radial-gradient(ellipse 96% 150% at 14% 50%, hsl(var(--deal-row-hue) 96% 64% / 0.52) 0%, transparent 60%),
    radial-gradient(ellipse 80% 130% at 86% 52%, hsl(calc(var(--deal-row-hue) + 26) 92% 66% / 0.34) 0%, transparent 64%),
    radial-gradient(ellipse 120% 180% at 50% 50%, hsl(var(--deal-row-hue) 90% 58% / 0.18) 0%, transparent 72%);
  filter: saturate(1.24) blur(0.35px);
  box-shadow: none;
}
.deal-track-lab-row:focus-visible {
  outline: 2px solid rgba(196, 181, 253, 0.68);
  outline-offset: 1px;
}
.deal-track-lab-row--active {
  background:
    radial-gradient(ellipse 95% 130% at 16% 50%, var(--deal-lab-section-active-bg) 0%, transparent 58%),
    linear-gradient(
      135deg,
      rgba(45, 212, 191, 0.16),
      rgba(99, 102, 241, 0.16),
      rgba(167, 139, 250, 0.16)
    );
  border-color: rgba(167, 139, 250, 0.34);
  box-shadow: 0 12px 36px rgba(76, 29, 149, 0.22);
  margin-bottom: 2px;
}
.deal-track-lab-row--done:not(.deal-track-lab-row--active) {
  background: rgba(30, 41, 59, 0.28);
}
.deal-track-lab-row--active::before {
  opacity: 0.72;
  box-shadow:
    0 0 16px hsl(var(--deal-row-hue) 98% 66% / 0.46),
    0 0 34px hsl(calc(var(--deal-row-hue) + 18) 94% 64% / 0.34),
    0 0 54px hsl(calc(var(--deal-row-hue) + 34) 88% 62% / 0.24);
}
.deal-track-lab-row--done:not(.deal-track-lab-row--active)::before {
  opacity: 0.42;
  box-shadow:
    0 0 10px hsl(var(--deal-row-hue) 94% 62% / 0.24),
    0 0 22px hsl(calc(var(--deal-row-hue) + 18) 90% 64% / 0.2);
}
.deal-track-lab-col-label {
  width: 18px;
  height: 18px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10.2px;
  font-weight: 900;
  color: rgb(236 254 255 / 0.98);
  text-align: center;
  font-variant-numeric: tabular-nums;
  line-height: 1.05;
  letter-spacing: 0.01em;
  border: 1px solid hsl(var(--deal-row-hue) 92% 74% / 0.58);
  background:
    radial-gradient(circle at 28% 26%, rgb(255 255 255 / 0.42) 0%, transparent 38%),
    linear-gradient(
      145deg,
      hsl(var(--deal-row-hue) 92% 64% / 0.82) 0%,
      hsl(calc(var(--deal-row-hue) + 18) 88% 60% / 0.8) 52%,
      hsl(calc(var(--deal-row-hue) + 34) 84% 58% / 0.82) 100%
    );
  box-shadow:
    0 0 0 1px rgb(30 41 59 / 0.55),
    0 0 10px hsl(var(--deal-row-hue) 92% 60% / 0.34),
    0 0 16px hsl(calc(var(--deal-row-hue) + 24) 86% 62% / 0.28);
  transition:
    transform 0.14s ease,
    box-shadow 0.14s ease,
    border-color 0.14s ease,
    filter 0.14s ease;
}
.deal-track-lab-row:hover .deal-track-lab-col-label,
.deal-track-lab-row:focus-within .deal-track-lab-col-label {
  transform: translateY(-1px) scale(1.08);
  border-color: hsl(var(--deal-row-hue) 96% 78% / 0.8);
  box-shadow:
    0 0 0 1px rgb(30 41 59 / 0.65),
    0 0 12px hsl(var(--deal-row-hue) 96% 64% / 0.52),
    0 0 22px hsl(calc(var(--deal-row-hue) + 24) 90% 64% / 0.4),
    0 0 34px hsl(calc(var(--deal-row-hue) + 36) 84% 62% / 0.26);
  filter: saturate(1.15);
}
.deal-track-lab-row-text {
  font-size: 11.8px;
  font-family: "Inter Tight", "Bahnschrift", "Segoe UI Variable Text", "Segoe UI", "Roboto", sans-serif;
  font-weight: 650;
  font-stretch: 108%;
  color: #64748b;
  line-height: 1.02;
  letter-spacing: 0.01em;
