}

.deal-track-lab-row .deal-track-lab-deck-strip--compact {
  transform: scale(0.92);
}

/* Реально ужимаем высоту вертикальной строки: компактная полоска карт и мини-рубашки */
.deal-track-lab-row .deal-track-lab-deck-strip {
  padding: 2px 5px;
