/* Мобильный активный ход пользователя: космические боковые "гирлянды" по ободу экрана */
@media (max-width: 1024px) {
  .game-table-root.viewport-mobile .mobile-turn-edge-glow {
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 130;
    /* Небольшая подрезка снизу: не заходим в область южной панели с округлением */
    --mobile-turn-edge-cut-bottom: clamp(58px, 9vh, 92px);
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail {
    position: absolute;
    top: calc(max(10px, env(safe-area-inset-top)) + 50px);
    bottom: calc(max(10px, env(safe-area-inset-bottom)) + var(--mobile-turn-edge-cut-bottom));
    width: clamp(5px, 1.2vw, 9px);
    border-radius: 999px;
    overflow: hidden;
    opacity: 0;
    box-shadow:
      0 0 0 1px rgb(186 230 253 / 0.2),
      0 0 12px rgb(34 211 238 / 0.34),
      0 0 20px rgb(125 211 252 / 0.3),
      0 0 34px rgb(139 92 246 / 0.2);
    background:
      linear-gradient(
        180deg,
        rgb(236 254 255 / 0.85) 0%,
        rgb(34 211 238 / 0.92) 20%,
        rgb(56 189 248 / 0.9) 40%,
        rgb(99 102 241 / 0.86) 62%,
        rgb(147 51 234 / 0.86) 80%,
        rgb(216 180 254 / 0.88) 100%
      );
    background-size: 100% 250%;
    /* Мягко растворяем нижнюю часть вместо резкого обрыва */
    -webkit-mask-image: linear-gradient(
      to bottom,
      rgb(0 0 0 / 0) 0%,
      rgb(0 0 0 / 1) 5%,
      rgb(0 0 0 / 1) 72%,
      rgb(0 0 0 / 0.68) 86%,
      rgb(0 0 0 / 0) 100%
    );
    mask-image: linear-gradient(
      to bottom,
      rgb(0 0 0 / 0) 0%,
      rgb(0 0 0 / 1) 5%,
      rgb(0 0 0 / 1) 72%,
      rgb(0 0 0 / 0.68) 86%,
      rgb(0 0 0 / 0) 100%
    );
    transform: translateZ(0) scaleX(0.45);
    transform-origin: center center;
    animation:
      mobile-turn-edge-rail-enter 760ms cubic-bezier(0.2, 0.82, 0.24, 1) forwards,
      mobile-turn-edge-rail-flow 3.1s linear 420ms infinite;
    will-change: background-position, filter;
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background:
      radial-gradient(ellipse at 50% 5%, rgb(255 255 255 / 1) 0%, rgb(255 255 255 / 0.88) 10%, rgb(255 255 255 / 0.46) 22%, rgb(255 255 255 / 0) 48%),
      linear-gradient(
        180deg,
        rgb(255 255 255 / 0.78) 0%,
        rgb(224 242 254 / 0.38) 12%,
        rgb(255 255 255 / 0.14) 24%,
        rgb(255 255 255 / 0) 42%
      ),
      repeating-linear-gradient(
        180deg,
        rgb(255 255 255 / 0.52) 0 6px,
        rgb(255 255 255 / 0.08) 6px 14px
      );
    mix-blend-mode: screen;
    backdrop-filter: blur(0.4px) saturate(1.14) brightness(1.1);
    -webkit-backdrop-filter: blur(0.4px) saturate(1.14) brightness(1.1);
    animation:
      mobile-turn-edge-spark 1.15s ease-in-out infinite alternate,
      mobile-turn-edge-top-flash 1.75s ease-in-out infinite;
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -14%;
    width: 340%;
    height: 44%;
    border-radius: 999px;
    transform: translateX(-50%);
    background:
      radial-gradient(ellipse at 50% 26%, rgb(216 180 254 / 0.34) 0%, rgb(125 211 252 / 0.24) 28%, rgb(34 211 238 / 0.14) 46%, rgb(34 211 238 / 0) 82%),
      radial-gradient(ellipse at 50% 64%, rgb(255 255 255 / 0.24) 0%, rgb(255 255 255 / 0) 62%);
    filter: blur(2.4px);
    opacity: 0.76;
    animation: mobile-turn-edge-nebula-tail 3.6s ease-in-out infinite;
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail--left {
    left: max(4px, env(safe-area-inset-left));
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail--right {
    right: max(4px, env(safe-area-inset-right));
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail--right::before {
    animation-delay: 0s;
  }

  .game-table-root.viewport-mobile .mobile-turn-edge-glow__rail--right::after {
    animation-delay: 0s;
  }

}

@keyframes mobile-turn-edge-rail-flow {
  0% {
    background-position: 50% 0%;
    filter: saturate(1) brightness(0.94);
  }
  50% {
    background-position: 50% 45%;
    filter: saturate(1.24) brightness(1.06);
  }
  100% {
    background-position: 50% 100%;
    filter: saturate(1.08) brightness(0.96);
  }
}

@keyframes mobile-turn-edge-rail-enter {
  0% {
    opacity: 0;
    transform: translateZ(0) scaleX(0.34);
    filter: saturate(0.9) brightness(0.9);
  }
  55% {
    opacity: 0.72;
    transform: translateZ(0) scaleX(0.86);
    filter: saturate(1.08) brightness(1.02);
  }
  100% {
    opacity: 0.9;
    transform: translateZ(0) scaleX(1);
    filter: saturate(1) brightness(0.98);
  }
}

@keyframes mobile-turn-edge-spark {
  0% {
    opacity: 0.42;
    transform: scaleY(0.985);
  }
  100% {
    opacity: 0.86;
    transform: scaleY(1.02);
  }
}

@keyframes mobile-turn-edge-comet {
  0% {
    top: -32%;
    opacity: 0.3;
  }
  20% {
    opacity: 0.9;
  }
  100% {
    top: 106%;
    opacity: 0.15;
  }
}

@keyframes mobile-turn-edge-nebula-tail {
  0% {
    opacity: 0.45;
    transform: translateX(-50%) scale(0.88, 0.84);
    filter: blur(2.8px) saturate(0.95);
  }
  50% {
    opacity: 0.88;
    transform: translateX(-50%) scale(1.04, 1.08);
    filter: blur(2.1px) saturate(1.12);
  }
  100% {
    opacity: 0.52;
    transform: translateX(-50%) scale(0.92, 0.9);
    filter: blur(3px) saturate(0.98);
  }
}

@keyframes mobile-turn-edge-top-flash {
  0%,
  100% {
    filter: brightness(1) saturate(1);
    opacity: 0.9;
  }
  42% {
    filter: brightness(1.28) saturate(1.18);
    opacity: 1;
  }
  56% {
    filter: brightness(1.42) saturate(1.26);
    opacity: 1;
  }
  72% {
    filter: brightness(1.12) saturate(1.08);
    opacity: 0.96;
  }
}

