/* Модалка: один проход подсветки по орбите — только transform на композиторе (без шагов React). */
.deal-track-lab-orbit-css-sweep {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  border-radius: inherit;
}

.deal-track-lab-orbit-css-sweep-rotor {
  position: absolute;
  inset: 0;
  transform-origin: 210px 210px;
  will-change: transform;
  animation: deal-track-lab-orbit-css-sweep-rot var(--orbit-css-sweep-ms, 1050ms) cubic-bezier(0.33, 0.92, 0.35, 1)
    forwards;
}

.deal-track-lab-orbit-css-sweep-spot {
  transition: none !important;
  left: 210px;
  top: 34px;
}

@keyframes deal-track-lab-orbit-css-sweep-rot {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(calc(360deg * (var(--orbit-css-sweep-segments) - 1) / var(--orbit-css-sweep-segments)));
  }
}

/*
 * Центр: сирень/фиолет — верхним слоями (голубые иначе «забивают» глаз);
