  opacity: 0.5;
  /* лёгкий объём торца без mix-blend (он давал резкую «полосу» по окружности) */
  box-shadow:
    inset 0 14px 20px rgba(15, 23, 42, 0.38),
    inset 0 -8px 16px rgba(255, 255, 255, 0.07),
    inset 0 0 0 1px rgba(186 217 251 / 0.22);
