/* Шарики выше слоя «пончика», но ниже текста центра — центр точки по орбите (inline left/top). */
.deal-track-lab-circle > button.deal-track-lab-point,
.deal-track-lab-circle > span.deal-track-lab-point {
  position: absolute;
  z-index: 4;
  transform: translate(-50%, -50%);
  /* на диске — чуть глубже базы, но так же «светлая» ямка (не тушуем цвет) */
  --deal-crater-inner:
    inset 0 9px 17px rgb(15 23 42 / 0.4),
    inset 0 -5px 11px rgb(255 255 255 / 0.1),
    inset 0 -1px 3px rgb(186 206 229 / 0.17),
    inset 0 0 0 1px rgb(30 41 59 / 0.82);
  --deal-crater-outer:
    0 1px 0 rgb(255 255 255 / 0.08),
    0 3px 8px rgb(2 6 23 / 0.42),
    0 6px 14px rgb(2 6 23 / 0.2);
}
.deal-track-lab-circle > button.deal-track-lab-point--active,
.deal-track-lab-circle > span.deal-track-lab-point--active {
  transform: translate(-50%, -50%);
  z-index: 5;
}
.deal-track-lab-circle > button.deal-track-lab-point:hover:not(.deal-track-lab-point--active),
.deal-track-lab-circle > button.deal-track-lab-point:focus-visible:not(.deal-track-lab-point--active) {
  transform: translate(-50%, calc(-50% - 1px)) scale(var(--deal-lab-point-active-mult));
}
.deal-track-lab-circle > button.deal-track-lab-point--active:hover,
.deal-track-lab-circle > button.deal-track-lab-point--active:focus-visible {
  transform: translate(-50%, calc(-50% - 1px)) scale(calc(var(--deal-lab-point-active-mult) * 1.06));
