}

.game-deal-orbit-dock__mini
  .deal-track-lab-circle-center-preview-wrap
  .deal-track-lab-circle-center-label-bar {
  display: none;
}

/* Вместо «Выбрано» — сиреневая градиентная полоса при наведении на другую раздачу */
.deal-track-lab-circle-center-label-bar {
  flex-shrink: 0;
  width: min(172px, 82%);
  min-width: 140px;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    #ede9fe 0%,
    #c4b5fd 22%,
    #a78bfa 48%,
    #d8b4fe 72%,
    #e9d5ff 100%
  );
  box-shadow:
    0 0 12px rgb(167 139 250 / 0.65),
    0 0 22px rgb(192 132 252 / 0.45),
    0 0 8px rgb(139 92 246 / 0.4),
    inset 0 1px 0 rgb(255 255 255 / 0.35);
}
.deal-track-lab-circle-center-num {
  display: inline-block;
  margin-top: -14px;
  /* WebKit + background-clip:text: без бокового запаса обрезаются 6/8/9/0; отриц. tracking ужимает маску сильнее букв */
  padding: 0.03em 0.11em 0.05em;
  font-size: 66px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: -0.018em;
  font-variant-numeric: tabular-nums;
}

/* Центральная цифра только большого круга B — палитра через переменные на .deal-track-lab-circle-wrap--in-row */
.deal-track-lab-circle-wrap--in-row .deal-track-lab-circle-center-num {
  background: linear-gradient(
    124deg,
    var(--dtl-num-g1) 0%,
    var(--dtl-num-g2) 12%,
    var(--dtl-num-g3) 26%,
    var(--dtl-num-g4) 38%,
    var(--dtl-num-g5) 50%,
    var(--dtl-num-g6) 56%,
    var(--dtl-num-g7) 70%,
    var(--dtl-num-g8) 86%,
    var(--dtl-num-g9) 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 2px 0 rgb(var(--dtl-num-rgb-engrave) / 0.92))
    drop-shadow(0 3px 2px rgb(var(--dtl-num-rgb-depth) / 0.38))
    drop-shadow(0 -1px 0 rgb(var(--dtl-num-rgb-highlight) / 0.22))
    drop-shadow(0 0 12px rgb(var(--dtl-num-rgb-glow-v) / 0.58))
    drop-shadow(0 0 24px rgb(var(--dtl-num-rgb-glow-i) / 0.38))
    drop-shadow(0 8px 18px rgb(var(--dtl-num-rgb-depth) / 0.45));
}

/* Удержание превью после клика по точке орбиты — розово‑фуксиевый акцент номера */
.deal-track-lab-circle-wrap--in-row .deal-track-lab-circle-center-num.deal-track-lab-circle-center-num--orbit-hold-pink {
  background: linear-gradient(
    118deg,
    #fff1f2 0%,
    #ffe4e6 9%,
    #fda4af 24%,
    #fb7185 38%,
    #f43f5e 50%,
    #ec4899 61%,
    #d946ef 73%,
    #f0abfc 86%,
    #fce7f3 96%,
    #ffffff 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 2px 0 rgb(136 19 55 / 0.52))
    drop-shadow(0 0 16px rgb(244 63 94 / 0.52))
    drop-shadow(0 0 30px rgb(236 72 153 / 0.4))
    drop-shadow(0 0 44px rgb(217 70 239 / 0.26))
    drop-shadow(0 -1px 0 rgb(255 255 255 / 0.42))
    drop-shadow(0 7px 18px rgb(15 23 42 / 0.38));
}

/*
 * Малый диск: бирюзовый неон в покое; на ховере кнопки реплики — тот же оранжевый акцент, что раньше был покоем.
 */
.deal-track-lab-orbit-replica-inner .deal-track-lab-circle-center-num:not(.deal-track-lab-circle-center-num--launch-scale) {
  margin-top: -14px;
  padding: 0.05em 0.1em 0.06em;
  font-size: 108px;
  letter-spacing: -0.026em;
  background: linear-gradient(
    108deg,
    #ecfeff 0%,
    #cffafe 12%,
    #5eead4 28%,
    #2dd4bf 42%,
    #14b8a6 54%,
    #22d3ee 68%,
    #67e8f9 82%,
    #ccfbf1 94%,
    #f0fdfa 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 1px 0 rgb(17 94 89 / 0.74))
    drop-shadow(0 0 16px rgb(34 211 238 / 0.38))
    drop-shadow(0 0 28px rgb(20 184 166 / 0.26))
    drop-shadow(0 2px 8px rgb(15 23 42 / 0.55));
  transition: filter 0.38s ease, transform 0.1s ease;
}

.deal-track-lab-orbit-replica-btn:hover
  .deal-track-lab-orbit-replica-inner
  .deal-track-lab-circle-center-num:not(.deal-track-lab-circle-center-num--launch-scale),
.deal-track-lab-orbit-replica-btn:has(:focus-visible)
  .deal-track-lab-orbit-replica-inner
  .deal-track-lab-circle-center-num:not(.deal-track-lab-circle-center-num--launch-scale) {
  transform: none;
  background: linear-gradient(
    112deg,
    #fffbeb 0%,
    #ffedd5 14%,
    #fdba74 32%,
    #ea580c 48%,
    #f97316 58%,
    #fb923c 72%,
    #fdba74 88%,
    #fff7ed 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 1px 0 rgb(154 52 18 / 0.72))
    drop-shadow(0 0 16px rgb(251 146 60 / 0.38))
    drop-shadow(0 0 28px rgb(234 88 12 / 0.22))
    drop-shadow(0 2px 8px rgb(15 23 42 / 0.55));
}

/* Кнопка «полная шкала»: в покое — цифра; при :hover/:focus-visible на самой кнопке — иконка «развернуть» */
.deal-track-lab-orbit-replica-inner button.deal-track-lab-circle-center-num--launch-scale {
  pointer-events: auto;
  cursor: pointer;
  position: relative;
  z-index: 9;
  isolation: isolate;
  display: inline-grid;
  place-items: center;
  border: none;
  margin: 0;
  padding: 0;
  transition: transform 0.1s ease;
  border-radius: 999px;
  overflow: visible;
  -webkit-appearance: none;
  appearance: none;
  text-align: center;
  -webkit-tap-highlight-color: transparent;
  background: none;
  filter: none;
  box-shadow: none;
  color: inherit;
  -webkit-text-fill-color: inherit;
}

.deal-track-lab-circle-center-launch-icon-svg {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
}

.deal-track-lab-orbit-replica-inner button.deal-track-lab-circle-center-num--launch-scale .deal-track-lab-circle-center-num-glyph--launch-idle {
  grid-area: 1 / 1;
  position: relative;
  z-index: 2;
  pointer-events: none;
  margin-top: -14px;
  padding: 0.05em 0.1em 0.06em;
  font-size: 108px;
  font-weight: 950;
  line-height: 1;
  letter-spacing: -0.026em;
  font-variant-numeric: tabular-nums;
  opacity: 1;
  transition:
    opacity 0.22s ease,
    transform 0.1s ease,
    filter 0.38s ease,
    background 0.38s ease;
  background: linear-gradient(
    108deg,
    #ecfeff 0%,
    #cffafe 12%,
    #5eead4 28%,
    #2dd4bf 42%,
    #14b8a6 54%,
    #22d3ee 68%,
    #67e8f9 82%,
    #ccfbf1 94%,
    #f0fdfa 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  filter:
    drop-shadow(0 1px 0 rgb(17 94 89 / 0.74))
    drop-shadow(0 0 16px rgb(34 211 238 / 0.38))
    drop-shadow(0 0 28px rgb(20 184 166 / 0.26))
    drop-shadow(0 2px 8px rgb(15 23 42 / 0.55));
}

.deal-track-lab-orbit-replica-inner
  button.deal-track-lab-circle-center-num--launch-scale:hover
  .deal-track-lab-circle-center-num-glyph--launch-idle,
.deal-track-lab-orbit-replica-inner
  button.deal-track-lab-circle-center-num--launch-scale:focus-visible
  .deal-track-lab-circle-center-num-glyph--launch-idle {
  opacity: 0;
}

.deal-track-lab-orbit-replica-inner button.deal-track-lab-circle-center-num--launch-scale .deal-track-lab-circle-center-launch-icon {
  grid-area: 1 / 1;
  position: relative;
  z-index: 3;
  pointer-events: none;
  width: 54px;
  height: 54px;
  margin-top: -10px;
  opacity: 0;
  /* Базовый цвет совпадает с «Открыть» на плашке (до анимации появления) */
  color: #fde047;
  filter:
    drop-shadow(0 1px 0 rgb(154 52 18 / 0.85))
    drop-shadow(0 0 12px rgb(251 146 60 / 0.55))
    drop-shadow(0 0 24px rgb(234 88 12 / 0.34))
    drop-shadow(0 -1px 0 rgb(255 255 255 / 0.38));
  transition:
    opacity 0.22s ease,
    transform 0.38s ease,
    filter 0.38s ease,
    color 0.38s ease;
}

.deal-track-lab-orbit-replica-inner
  button.deal-track-lab-circle-center-num--launch-scale:hover
  .deal-track-lab-circle-center-launch-icon,
.deal-track-lab-orbit-replica-inner
  button.deal-track-lab-circle-center-num--launch-scale:focus-visible
  .deal-track-lab-circle-center-launch-icon {
  opacity: 1;
}

/* Точка в центре глифа — в тон «Открыть» (янтарь/золото) */
