      rgb(129 140 248) 0%,
      rgb(99 102 241) 16%,
      rgb(79 70 229) 34%,
      rgb(67 56 202) 52%,
      rgb(55 48 163) 68%,
      rgb(37 99 235 / 0.92) 82%,
