    0 0 0 1px rgb(165 180 252 / 0.38) inset,
    0 3px 12px rgb(224 231 255 / 0.18) inset,
    0 -12px 28px rgb(15 23 42 / 0.58) inset,
    0 -1px 0 rgb(96 165 250 / 0.26) inset,
