  opacity: 0;
  transform: scale(0.9);
  transition:
    opacity 0.24s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.deal-track-lab-orbit-replica-inner button.deal-track-lab-circle-center-num--launch-scale::after {
  content: '';
  position: absolute;
  z-index: 1;
  left: 50%;
