  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.4em;
  row-gap: 0.2em;
  filter: drop-shadow(0 1px 0 rgba(15, 23, 42, 0.65));
}

.deal-track-lab-circle-center-cap-hand {
  display: inline;
  white-space: nowrap;
}

/* Режим (БК / тёмная) всегда над строкой «КАРТ:» — отдельные ряды, без склеивания в одну линию flex-wrap */
.deal-track-lab-circle-center-cap--two-rows {
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
}

.deal-track-lab-circle-center-cap--two-rows .deal-track-lab-circle-center-cap-mode {
  display: block;
  width: 100%;
  max-width: 100%;
  text-align: center;
}

.deal-track-lab-circle-center-cap--two-rows .deal-track-lab-circle-center-cap-hand {
  display: inline-flex;
  align-items: baseline;
  justify-content: center;
  /* Как у обычной строки «КАРТ: n» (inline): во flex пробел в JSX не даёт зазора без gap */
  gap: 0.22em;
  /* Бескозырка / тёмная: плотнее между строкой режима и «КАРТ:» */
  margin-top: -4px;
}

/* «Бескозырка» длиннее «Тёмная» — чуть меньше, чтобы уложиться в мини-диск орбиты (только БК) */
.deal-track-lab-orbit-replica-inner
  .deal-track-lab-circle-center-cap--two-rows
  .deal-track-lab-circle-center-cap-mode--no-trump {
  font-size: 0.88em;
}

.deal-track-lab-circle-center-cap-mode,
.deal-track-lab-circle-center-cap-hand-prefix {
  background: linear-gradient(
    95deg,
    #93c5fd 0%,
    #bae6fd 18%,
    #e9d5ff 52%,
    #d8b4fe 82%,
    #f5d0fe 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
}

/* Мини-диск: только префикс «КАРТ:» на 2px меньше строки с числом */
.deal-track-lab-orbit-replica-inner .deal-track-lab-circle-center-cap-hand-prefix {
  font-size: calc(1em - 2px);
}

/* Мини-диск: число N — полный размер капа (не как у «КАРТ:») */
.deal-track-lab-orbit-replica-inner .deal-track-lab-circle-center-cap-num {
  font-size: 1em;
}

