  -webkit-text-fill-color: hsl(212 92% 98%);
  transform: translateY(0.5px);
  text-shadow:
    /* контраст со сферой */
    0 1px 0 rgb(15 23 42 / 0.75),
    0 2px 3px rgb(15 23 42 / 0.55),
    /* «неон»: оттенок раздачи + циан/сирень */
    0 0 8px hsl(var(--deal-hue) 92% 58% / 0.9),
    0 0 14px rgb(34 211 238 / 0.65),
