  margin: 0;
  padding: 12px 12px 10px;
  border-radius: 18px 18px 14px 14px;
  border: 2px solid transparent;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background-color: rgba(8, 6, 28, 0.98);
  background-image:
    radial-gradient(120% 80% at 12% -8%, rgba(34, 211, 238, 0.2) 0%, transparent 52%),
    radial-gradient(90% 70% at 92% 108%, rgba(168, 85, 247, 0.18) 0%, transparent 55%),
    linear-gradient(168deg, rgba(30, 27, 75, 0.94) 0%, rgba(15, 23, 42, 0.98) 48%, rgba(2, 6, 23, 0.99) 100%),
    linear-gradient(
      125deg,
      #3b0764 0%,
      #6d28d9 22%,
      #8b5cf6 38%,
      #22d3ee 58%,
      #38bdf8 78%,
      #a78bfa 100%
    );
  background-clip: padding-box, padding-box, padding-box, border-box;
  background-origin: padding-box, padding-box, padding-box, border-box;
  box-shadow:
    0 0 0 1px rgba(34, 211, 238, 0.38),
