/* Герой-аватар: космическое кольцо + объём «стеклянного шара» (как на столе, крупнее) */
.avatar-menu-sheet-avatar-stage {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 84px;
  height: 84px;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  border-radius: 50%;
  transition: transform 0.18s ease;
}

.avatar-menu-sheet-avatar-stage--clickable {
  cursor: pointer;
}

.avatar-menu-sheet-avatar-stage--clickable::before {
  content: '';
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 2px solid rgba(34, 211, 238, 0.45);
  box-shadow:
    0 0 0 1px rgba(167, 139, 250, 0.25),
    0 0 18px rgba(34, 211, 238, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
  animation: avatar-menu-sheet-tap-ring 2.2s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}

.avatar-menu-sheet-avatar-stage--clickable .avatar-menu-sheet-avatar-ring {
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.22),
    0 1px 0 rgba(255, 255, 255, 0.28) inset,
    0 10px 28px rgba(0, 0, 0, 0.5),
    0 0 40px rgba(124, 58, 237, 0.48),
    0 0 28px rgba(34, 211, 238, 0.42);
}

.avatar-menu-sheet-avatar-stage--clickable .avatar-menu-sheet-avatar-halo {
  animation: avatar-menu-sheet-halo-pulse 2.2s ease-in-out infinite;
}

@keyframes avatar-menu-sheet-tap-ring {
  0%,
  100% {
    opacity: 0.72;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.03);
  }
}

.avatar-menu-sheet-avatar-stage:hover:not(:disabled) {
  transform: scale(1.04);
}

.avatar-menu-sheet-avatar-stage--clickable:hover:not(:disabled) .avatar-menu-sheet-avatar-ring {
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.3),
    0 2px 0 rgba(255, 255, 255, 0.32) inset,
    0 12px 32px rgba(0, 0, 0, 0.52),
    0 0 48px rgba(34, 211, 238, 0.55),
    0 0 32px rgba(167, 139, 250, 0.45);
}

.avatar-menu-sheet-avatar-stage:active:not(:disabled) {
  transform: scale(0.98);
}

.avatar-menu-sheet-avatar-stage:disabled {
  cursor: default;
}

.avatar-menu-sheet-avatar-stage:focus-visible {
  outline: 2px solid rgba(34, 211, 238, 0.85);
  outline-offset: 4px;
}

.avatar-menu-sheet-avatar-halo {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 42%, rgba(34, 211, 238, 0.35) 0%, transparent 52%),
    radial-gradient(circle at 50% 58%, rgba(167, 139, 250, 0.28) 0%, transparent 58%);
  filter: blur(2px);
  animation: avatar-menu-sheet-halo-pulse 3.2s ease-in-out infinite;
}

@keyframes avatar-menu-sheet-halo-pulse {
  0%,
  100% {
    opacity: 0.85;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.04);
  }
}

.avatar-menu-sheet-avatar-ring {
  position: relative;
  z-index: 1;
  padding: 4px;
  border-radius: 50%;
  background: linear-gradient(
    145deg,
    #22d3ee 0%,
    #a78bfa 32%,
    #c084fc 52%,
    #38bdf8 78%,
    #22d3ee 100%
  );
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.14),
    0 10px 28px rgba(0, 0, 0, 0.5),
    0 0 32px rgba(124, 58, 237, 0.38),
    0 0 22px rgba(34, 211, 238, 0.28);
}

.avatar-menu-sheet-avatar-ring::after {
  content: '';
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  pointer-events: none;
  z-index: 3;
  background: radial-gradient(
    circle at 32% 24%,
    rgba(255, 255, 255, 0.5) 0%,
    rgba(255, 255, 255, 0.12) 28%,
    transparent 52%
