  background: #020617;
}

.avatar-editor-inpage-camera__actions {
  display: flex;
  gap: 8px;
  justify-content: center;
  width: 100%;
}

.avatar-editor-modal-card {
  position: relative;
  isolation: isolate;
  width: 100%;
  max-width: min(380px, 100%);
  max-height: min(94dvh, 640px);
  overflow-x: hidden;
  overflow-y: visible;
  box-sizing: border-box;
  margin: 0;
  padding: 4px 12px 8px;
  border-radius: 14px;
  border: 2px solid transparent;
  background-color: rgba(8, 6, 28, 0.98);
  background-image:
    radial-gradient(120% 80% at 12% -8%, rgba(34, 211, 238, 0.18) 0%, transparent 52%),
    radial-gradient(90% 70% at 92% 108%, rgba(168, 85, 247, 0.16) 0%, transparent 55%),
    linear-gradient(168deg, rgba(30, 27, 75, 0.94) 0%, rgba(15, 23, 42, 0.98) 48%, rgba(2, 6, 23, 0.99) 100%),
