  grid-template-columns: minmax(42px, 1fr) auto max-content;
  grid-template-rows: auto auto auto auto;
  align-items: stretch;
  column-gap: 14px;
  row-gap: 2px;
  margin: 0 0 6px;
  padding: 0;
}

.avatar-editor-hero__wing {
  align-self: stretch;
  min-height: 0;
  width: 40px;
  justify-items: center;
}

.avatar-editor-hero__wing--left {
  grid-column: 1;
  grid-row: 2;
  justify-self: end;
  padding-right: 4px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  align-items: center;
}

.avatar-editor-hero__canvas {
  grid-column: 2;
  grid-row: 2;
  justify-self: center;
  align-self: center;
}

.avatar-editor-hero__wing--right {
  grid-column: 3;
  grid-row: 2;
  justify-self: start;
  width: auto;
  min-width: 40px;
  max-width: 76px;
  padding-left: 0;
  display: grid;
  grid-template-rows: auto 1fr auto;
  justify-items: center;
  align-items: center;
}

.avatar-editor-hero__wing--right .avatar-editor-hero__slot--top {
  grid-row: 1;
  align-self: start;
  justify-self: center;
  margin-top: 13px;
}

