.avatar-editor-hero__wing--right .avatar-editor-hero__slot--bottom {
  grid-row: 3;
  align-self: end;
  justify-self: center;
}

.avatar-editor-hero__wing--left .avatar-editor-hero__slot--top {
  grid-row: 1;
  align-self: start;
  justify-self: center;
  margin-top: 8px;
}

.avatar-editor-hero__wing--left .avatar-editor-hero__slot--bottom {
  grid-row: 3;
  align-self: end;
  justify-self: center;
}

.avatar-editor-hero__slot--mid {
  grid-row: 2;
  align-self: center;
  justify-self: center;
}

.avatar-editor-hero__slot--top {
