.avatar-editor-template-chip--nebula {
  background: linear-gradient(135deg, #22d3ee, #7c3aed, #0f172a);
}

.avatar-editor-template-chip--aurora {
  background: linear-gradient(135deg, #064e3b, #22d3ee, #1e1b4b);
}

.avatar-editor-template-chip--ember {
  background: linear-gradient(135deg, #ea580c, #f472b6, #312e81);
}

.avatar-editor-template-chip--violet-crown {
  background: linear-gradient(135deg, #fde68a, #c084fc, #5b21b6);
}

.avatar-editor-template-chip--deep-space {
  background: radial-gradient(circle at 30% 30%, #fff 1px, transparent 1px), #020617;
  background-size: 8px 8px;
}

.avatar-editor-template-chip--prism {
  background: linear-gradient(135deg, #f472b6, #a78bfa, #38bdf8, #fbbf24);
}

.avatar-editor-template-chip--none {
  background:
    linear-gradient(45deg, rgba(148, 163, 184, 0.22) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(148, 163, 184, 0.22) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(148, 163, 184, 0.22) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(148, 163, 184, 0.22) 75%),
    #0f172a;
  background-size: 8px 8px;
  background-position: 0 0, 0 4px, 4px -4px, -4px 0;
  border-style: dashed;
  border-color: rgba(148, 163, 184, 0.45);
}

.avatar-editor-template-chip--initials {
  background: linear-gradient(135deg, #475569, #6366f1);
}

.avatar-editor-tools-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.avatar-editor-history-col {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex-shrink: 0;
}

.avatar-editor-history-btn,
.avatar-editor-3d-btn {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  border-radius: 12px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.avatar-editor-history-btn {
  flex-direction: column;
  gap: 1px;
  width: 40px;
  height: 36px;
  padding: 3px 4px;
  border: 1px solid rgba(34, 211, 238, 0.5);
  background: linear-gradient(168deg, rgba(14, 116, 144, 0.45) 0%, rgba(15, 23, 42, 0.92) 100%);
  color: #67e8f9;
  box-shadow: 0 0 12px rgba(34, 211, 238, 0.18);
}

.avatar-editor-history-btn:disabled {
  opacity: 0.38;
  cursor: default;
  color: #64748b;
  border-color: rgba(148, 163, 184, 0.35);
  box-shadow: none;
}

.avatar-editor-history-btn__icon {
  font-size: 16px;
  font-weight: 800;
  line-height: 1;
}

.avatar-editor-history-btn__label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.05;
  opacity: 0.92;
}

.avatar-editor-clear-btn {
  flex-shrink: 0;
  display: inline-flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: auto;
  max-width: 100%;
  height: auto;
  min-height: 0;
  justify-self: center;
  padding: 0 10px;
  gap: 0;
  border-radius: 10px;
  border: 1px solid rgba(167, 139, 250, 0.52);
  background:
    linear-gradient(168deg, rgba(88, 28, 135, 0.38) 0%, rgba(14, 116, 144, 0.22) 48%, rgba(15, 23, 42, 0.94) 100%);
  color: #c4b5fd;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  box-shadow:
    0 0 10px rgba(167, 139, 250, 0.18),
    0 0 8px rgba(34, 211, 238, 0.1);
}

.avatar-editor-clear-btn:hover {
  transform: translateX(-4px);
  border-color: rgba(103, 232, 249, 0.62);
  box-shadow:
    0 0 14px rgba(167, 139, 250, 0.32),
    0 0 10px rgba(244, 114, 182, 0.22);
}

.avatar-editor-clear-btn__label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1;
  white-space: nowrap;
  background: linear-gradient(100deg, #67e8f9 0%, #c4b5fd 40%, #f472b6 72%, #a5b4fc 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 6px rgba(34, 211, 238, 0.28));
}

.avatar-editor-3d-btn {
  width: 40px;
  height: 40px;
}

.avatar-editor-color {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.25);
  cursor: pointer;
  padding: 0;
}

.avatar-editor-color--active {
  border-color: #22d3ee;
  box-shadow: 0 0 0 2px rgba(34, 211, 238, 0.45);
}

.avatar-editor-color--flat {
  border-radius: 4px;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.35);
}

.avatar-editor-tools-line--flat-brush .avatar-editor-color--active {
  border-color: rgba(148, 163, 184, 0.9);
  box-shadow:
    0 0 0 2px rgba(100, 116, 139, 0.55),
    inset 0 1px 2px rgba(0, 0, 0, 0.3);
}

/* Неоновая палитра «Цвета» */
.avatar-neon-picker {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.avatar-neon-picker__brush-mode {
  display: inline-flex;
  border-radius: 999px;
  border: 1px solid rgba(167, 139, 250, 0.45);
  overflow: hidden;
  flex-shrink: 0;
}

.avatar-neon-picker__brush-mode-btn {
  height: 24px;
  padding: 0 7px;
  border: none;
  background: rgba(30, 27, 75, 0.75);
  color: #94a3b8;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.02em;
  cursor: pointer;
}

.avatar-neon-picker__brush-mode-btn--active {
  color: #0f172a;
  background: linear-gradient(135deg, #22d3ee 0%, #a855f7 100%);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.35);
}

.avatar-neon-picker__trigger {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 0 8px 0 4px;
  border-radius: 999px;
  border: 1px solid rgba(167, 139, 250, 0.5);
  background: rgba(30, 27, 75, 0.75);
  cursor: pointer;
}

.avatar-neon-picker__trigger--open {
  border-color: rgba(34, 211, 238, 0.75);
  box-shadow: 0 0 12px rgba(34, 211, 238, 0.28);
}

.avatar-neon-picker__trigger-swatch {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.35);
  box-shadow: 0 0 8px rgba(34, 211, 238, 0.35);
}

.avatar-neon-picker__trigger-label {
  font-size: 10px;
  font-weight: 700;
  color: #c4b5fd;
}

.avatar-neon-picker__backdrop {
  position: fixed;
  inset: 0;
  z-index: 10019;
  pointer-events: none;
  background: rgba(2, 6, 23, 0.2);
}

.avatar-neon-picker__panel {
  position: fixed;
  z-index: 10020;
  box-sizing: border-box;
  max-width: calc(100vw - 20px);
  padding: 0 8px 8px;
  border-radius: 12px;
  border: 1px solid rgba(34, 211, 238, 0.55);
  background: rgba(6, 4, 22, 0.98);
  box-shadow:
    0 0 28px rgba(124, 58, 237, 0.4),
    0 12px 28px rgba(0, 0, 0, 0.55);
  touch-action: none;
}

.avatar-neon-picker__header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 -8px 6px;
  padding: 7px 8px 6px;
  border-radius: 12px 12px 0 0;
  border-bottom: 1px solid rgba(34, 211, 238, 0.25);
  background: rgba(15, 10, 40, 0.65);
  cursor: grab;
  user-select: none;
  touch-action: none;
}

.avatar-neon-picker__header:active {
  cursor: grabbing;
}

.avatar-neon-picker__drag {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 2px 4px;
  border-radius: 6px;
  background: rgba(34, 211, 238, 0.12);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.25);
}

.avatar-neon-picker__drag-col {
  font-size: 17px;
  font-weight: 900;
  line-height: 0.85;
  color: #67e8f9;
  text-shadow:
    0 0 10px rgba(34, 211, 238, 0.95),
    0 0 4px rgba(255, 255, 255, 0.6);
}

.avatar-neon-picker__title {
  flex: 1;
  min-width: 0;
  font-size: 11px;
  font-weight: 700;
  color: #c4b5fd;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.avatar-neon-picker__header-actions {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

.avatar-neon-picker__ok {
  height: 26px;
  padding: 0 10px;
  border: none;
  border-radius: 8px;
  background: linear-gradient(135deg, #22d3ee 0%, #7c3aed 100%);
  color: #0f172a;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
  box-shadow:
    0 0 12px rgba(34, 211, 238, 0.45),
    0 2px 6px rgba(0, 0, 0, 0.35);
}

.avatar-neon-picker__ok:hover {
  filter: brightness(1.08);
  color: #020617;
}

.avatar-neon-picker__close {
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: rgba(30, 27, 75, 0.9);
  color: #e2e8f0;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

.avatar-neon-picker__close:hover {
  background: rgba(124, 58, 237, 0.45);
  color: #fff;
}

.avatar-neon-picker__mode {
  display: flex;
  gap: 6px;
  margin-bottom: 6px;
}

.avatar-neon-picker__mode-btn {
  flex: 1;
  height: 28px;
  padding: 0 8px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.75);
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.avatar-neon-picker__mode-btn--active {
  border-color: rgba(34, 211, 238, 0.7);
  color: #ecfeff;
  background: linear-gradient(135deg, rgba(34, 211, 238, 0.35) 0%, rgba(124, 58, 237, 0.45) 100%);
  box-shadow: 0 0 14px rgba(34, 211, 238, 0.3);
}

.avatar-neon-picker__lead {
  margin: 0 0 6px;
  font-size: 9px;
  font-weight: 600;
  line-height: 1.2;
  color: #a5f3fc;
  text-align: center;
  letter-spacing: 0.02em;
}

.avatar-neon-picker__grid {
  display: grid;
  grid-template-columns: repeat(4, 32px);
  justify-content: center;
  gap: 6px;
  margin-bottom: 6px;
}

.avatar-neon-picker__swatch {
  width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.45);
  cursor: pointer;
  transition: transform 0.1s ease, filter 0.12s ease;
}

.avatar-neon-picker__swatch:hover {
  filter: brightness(1.2) saturate(1.15);
  transform: scale(1.06);
}

.avatar-neon-picker__swatch--active {
  border-color: #fff;
  outline: 1px solid #00f5ff;
  outline-offset: 0;
  transform: scale(1.1);
  filter: brightness(1.2) saturate(1.2);
  z-index: 1;
}

.avatar-neon-picker__swatch--flat {
  border-color: rgba(15, 23, 42, 0.45);
  border-radius: 4px;
}

.avatar-neon-picker__swatch--flat:hover {
  filter: brightness(1.06);
  transform: scale(1.04);
}

.avatar-neon-picker__grid--flat {
  gap: 5px;
}

.avatar-neon-picker__swatch--flat.avatar-neon-picker__swatch--active {
  border-color: rgba(15, 23, 42, 0.65);
  outline: 2px solid rgba(148, 163, 184, 0.85);
  outline-offset: 1px;
  filter: none;
  transform: scale(1.05);
}

.avatar-neon-picker__trigger-swatch--flat {
  border-radius: 4px;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.35);
}

.avatar-neon-picker__manual-title {
  margin: 4px 0 3px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}

.avatar-neon-picker__hex {
  width: 100%;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.25);
}

.avatar-neon-picker__hex .react-colorful {
  width: 100% !important;
  height: 92px !important;
}

.avatar-neon-picker__hex .react-colorful__saturation {
  border-radius: 9px 9px 0 0;
  border-bottom: none;
}

.avatar-neon-picker__hex .react-colorful__hue {
  height: 14px;
  border-radius: 0 0 9px 9px;
}

.avatar-neon-picker__hex-field {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 4px;
}

.avatar-neon-picker__hex-field-label {
  font-size: 10px;
  font-weight: 700;
  color: #64748b;
  flex-shrink: 0;
}

.avatar-neon-picker__hex-input {
  flex: 1;
  min-width: 0;
  padding: 4px 7px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.8);
  color: #e2e8f0;
  font-size: 12px;
  font-family: ui-monospace, monospace;
}

/* decor: одна строка через chip-rail */

.avatar-editor-3d-btn {
  padding: 6px;
  border: none;
  border-radius: 14px;
  background:
    radial-gradient(130% 110% at 28% 14%, rgba(224, 242, 254, 0.42) 0%, transparent 50%),
    radial-gradient(110% 95% at 78% 88%, rgba(76, 29, 149, 0.65) 0%, transparent 52%),
    linear-gradient(152deg, #6d28d9 0%, #312e81 42%, #0f172a 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.28) inset,
    0 2px 4px rgba(255, 255, 255, 0.08) inset,
    0 -3px 8px rgba(0, 0, 0, 0.5) inset,
    0 5px 14px rgba(0, 0, 0, 0.45),
    0 0 20px rgba(139, 92, 246, 0.45);
  transition: transform 0.12s ease, box-shadow 0.15s ease;
}

.avatar-editor-3d-btn:hover {
  transform: translateY(-1px);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.34) inset,
    0 2px 5px rgba(255, 255, 255, 0.1) inset,
    0 -3px 8px rgba(0, 0, 0, 0.48) inset,
    0 7px 18px rgba(0, 0, 0, 0.48),
    0 0 26px rgba(167, 139, 250, 0.55);
}

.avatar-editor-3d-btn:active {
  transform: translateY(1px) scale(0.97);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.14) inset,
    0 -1px 4px rgba(0, 0, 0, 0.55) inset,
    0 2px 8px rgba(0, 0, 0, 0.4),
    0 0 16px rgba(139, 92, 246, 0.35);
}

.avatar-editor-3d-btn__glyph {
  width: 30px;
  height: 30px;
  display: block;
  filter:
    drop-shadow(0 1px 0 rgba(255, 255, 255, 0.65))
    drop-shadow(0 2px 3px rgba(15, 23, 42, 0.75))
    drop-shadow(0 0 10px rgba(103, 232, 249, 0.85));
}

.avatar-editor-3d-btn--applied {
  background:
    radial-gradient(130% 110% at 28% 14%, rgba(165, 243, 252, 0.5) 0%, transparent 50%),
    radial-gradient(110% 95% at 78% 88%, rgba(14, 116, 144, 0.55) 0%, transparent 52%),
    linear-gradient(152deg, #0891b2 0%, #312e81 42%, #0f172a 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.32) inset,
    0 2px 4px rgba(255, 255, 255, 0.1) inset,
    0 -3px 8px rgba(0, 0, 0, 0.45) inset,
    0 5px 14px rgba(0, 0, 0, 0.42),
    0 0 24px rgba(34, 211, 238, 0.55);
}

.avatar-editor-3d-btn--applied .avatar-editor-3d-btn__glyph {
  filter:
    drop-shadow(0 1px 0 rgba(255, 255, 255, 0.75))
    drop-shadow(0 2px 3px rgba(15, 23, 42, 0.7))
    drop-shadow(0 0 12px rgba(34, 211, 238, 0.95));
}

.avatar-editor-frame-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 3px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.55);
  cursor: pointer;
}

.avatar-editor-frame-btn--active {
  border-color: rgba(34, 211, 238, 0.75);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.28);
}

.avatar-editor-frame-btn__img {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  object-fit: contain;
  pointer-events: none;
}

.avatar-editor-size {
  min-width: 26px;
  height: 22px;
  padding: 0 8px;
  border-radius: 7px;
  border: 1px solid rgba(148, 163, 184, 0.4);
  background: rgba(15, 23, 42, 0.6);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.avatar-editor-size--active {
  border-color: rgba(34, 211, 238, 0.7);
  color: #67e8f9;
}

.avatar-editor-tool-toggle {
  height: 22px;
  padding: 0 8px;
  border-radius: 7px;
  border: 1px solid rgba(148, 163, 184, 0.4);
  background: rgba(51, 65, 85, 0.5);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.avatar-editor-sticker-btn {
  min-width: 30px;
  height: 28px;
  padding: 0 6px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.55);
  color: #f8fafc;
  font-size: 17px;
  line-height: 1;
  cursor: pointer;
}

.avatar-editor-sticker-btn--active {
  border-color: rgba(34, 211, 238, 0.75);
  box-shadow: 0 0 10px rgba(34, 211, 238, 0.28);
  background: rgba(14, 116, 144, 0.35);
}

.avatar-editor-tool-toggle--active {
  border-color: rgba(251, 146, 60, 0.65);
  color: #fdba74;
}

.avatar-editor-modal-footer {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: 6px;
  margin-top: 4px;
}

.avatar-editor-modal-footer__spacer {
  flex: 1 1 auto;
  min-width: 4px;
}

@media (max-width: 520px) {
  .avatar-editor-modal-footer {
    flex-wrap: wrap;
  }

  .avatar-editor-modal-footer__spacer {
    display: none;
  }

  .avatar-editor-modal-footer .avatar-editor-modal-btn {
    flex: 1 1 calc(50% - 4px);
  }
}

.avatar-editor-file-actions {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 0;
}

.avatar-editor-file-input {
  display: none;
}

.avatar-editor-error {
  margin: 0 0 5px;
  font-size: 12px;
  color: #f87171;
}

.avatar-editor-modal-actions {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 6px;
  margin: 0;
}

.avatar-editor-modal-btn {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  border-radius: 10px;
  font: inherit;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.avatar-editor-modal-btn--compact {
  padding: 7px 9px;
  font-size: 12px;
  border-radius: 8px;
}

.avatar-editor-modal-btn--primary {
  border: 1px solid rgba(34, 211, 238, 0.65);
  color: #ecfeff;
  background: linear-gradient(168deg, rgba(14, 116, 144, 0.95) 0%, rgba(21, 94, 117, 0.98) 55%, rgba(15, 23, 42, 0.98) 100%);
}

.avatar-editor-modal-btn--secondary {
  border: 1px solid rgba(139, 92, 246, 0.55);
  color: #ede9fe;
  background: linear-gradient(168deg, rgba(76, 29, 149, 0.55) 0%, rgba(30, 27, 75, 0.92) 100%);
}

.avatar-editor-modal-btn--ghost {
  border: 1px solid rgba(148, 163, 184, 0.35);
  color: #94a3b8;
  background: rgba(15, 23, 42, 0.45);
  font-weight: 600;
}

.avatar-editor-modal-btn:disabled {
  opacity: 0.7;
  cursor: wait;
}

/* Узкий / низкий экран: скролл только при необходимости (не на широком ПК) */
@media (max-height: 520px), (max-width: 340px) {
  .avatar-editor-modal-card:not(.avatar-editor-modal-card--desktop) {
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    max-height: calc(100dvh - 12px);
    padding: 4px 8px 6px;
  }
}

@media (max-height: 520px) {
  .avatar-editor-modal-card--desktop {
    max-height: calc(100dvh - 24px);
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: thin;
    scrollbar-color: rgba(167, 139, 250, 0.45) transparent;
  }
}

@media (max-width: 320px) {
  .avatar-editor-hero {
    column-gap: 5px;
  }

  .avatar-editor-hero__wing {
    min-width: 36px;
