/* --- Онлайн-лобби (LobbyScreen): скролл + космический chrome --- */
html:has(.lobby-screen) {
  overflow: hidden;
  overflow-x: clip;
  overscroll-behavior: none;
  width: 100%;
  max-width: 100%;
}
body:has(.lobby-screen) {
  overflow: hidden;
  overflow-x: clip;
  overscroll-behavior: none;
  width: 100%;
  max-width: 100%;
  touch-action: none;
}
#root:has(.lobby-screen) {
  overflow-x: clip;
  max-width: 100%;
}
.lobby-screen {
  position: fixed;
  inset: 0;
  z-index: 100;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  background: #0f172a;
  overflow: hidden;
  isolation: isolate;
}
.lobby-screen:not(.lobby-screen--entry) {
  overflow-x: clip;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  touch-action: pan-y;
  scroll-padding-top: max(12px, env(safe-area-inset-top, 0px));
}
.lobby-screen--entry {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: #0f172a;
  /* body:has(.lobby-screen) ставит touch-action:none — иначе жесты не доходят до скролла layout */
  touch-action: pan-y;
}
.lobby-screen__stack {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  width: 100%;
  max-width: 340px;
  min-height: 100%;
  min-height: 100dvh;
  margin: 0 auto;
  padding:
    max(20px, env(safe-area-inset-top, 0px))
    max(16px, env(safe-area-inset-right, 0px))
    max(28px, env(safe-area-inset-bottom, 0px))
    max(16px, env(safe-area-inset-left, 0px));
  box-sizing: border-box;
  overflow-x: hidden;
}

/* Экран входа в онлайн: размытая аура + портрет маскота */
.lobby-screen__aura {
  position: fixed;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  overflow: clip;
  contain: paint;
  pointer-events: none;
}
.lobby-screen__aura-img {
  position: absolute;
  left: 50%;
  top: 42%;
  width: 100%;
  height: 100%;
  max-width: 100%;
  object-fit: cover;
  object-position: center;
  transform: translate(-50%, -50%) scale(1.35);
  filter: blur(34px) saturate(1.55) brightness(0.68);
  opacity: 0.62;
  will-change: transform;
}
.lobby-screen__aura-glow {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 92% 78% at 14% 24%, rgba(236, 72, 153, 0.58) 0%, transparent 58%),
    radial-gradient(ellipse 88% 74% at 86% 76%, rgba(34, 211, 238, 0.52) 0%, transparent 56%),
    radial-gradient(ellipse 55% 48% at 50% 50%, rgba(124, 58, 237, 0.28) 0%, transparent 68%);
  mix-blend-mode: screen;
  opacity: 0.92;
}
.lobby-screen__aura-scrim {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 118% 96% at 50% 44%, rgba(15, 23, 42, 0.02) 32%, rgba(15, 23, 42, 0.78) 100%),
    linear-gradient(180deg, rgba(15, 23, 42, 0.12) 0%, rgba(15, 23, 42, 0.5) 100%);
}
.lobby-screen__layout {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  width: 100%;
  max-width: 340px;
  min-height: auto;
  margin: 0 auto;
  padding:
    max(12px, env(safe-area-inset-top, 0px))
    max(16px, env(safe-area-inset-right, 0px))
    max(28px, env(safe-area-inset-bottom, 0px))
    max(16px, env(safe-area-inset-left, 0px));
  box-sizing: border-box;
  overflow-x: hidden;
}
.lobby-screen__layout--entry {
  position: relative;
  z-index: 1;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  max-width: 100%;
  margin: 0 auto;
  overflow-x: clip;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  touch-action: pan-y;
  scroll-padding-top: max(10px, env(safe-area-inset-top, 0px));
}
.lobby-screen__layout:not(.lobby-screen__layout--entry) {
  min-height: auto;
}
.lobby-screen__top-bar {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: 100%;
  max-width: 320px;
  flex-shrink: 0;
