  align-items: center;
  gap: 18px;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
}
.lobby-nav-back {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 28px;
  padding: 0 11px 0 5px;
  margin: 0;
  font-family: inherit;
  cursor: pointer;
  border: 1.5px solid transparent;
  border-radius: 4px 14px 14px 4px;
  background:
    linear-gradient(102deg, rgba(18, 12, 42, 0.92) 0%, rgba(8, 4, 22, 0.98) 100%) padding-box,
    linear-gradient(118deg, rgba(167, 139, 250, 0.75), rgba(34, 211, 238, 0.45), rgba(244, 114, 182, 0.55))
      border-box;
  box-shadow:
    inset 0 1px 0 rgba(196, 181, 253, 0.08),
    0 0 14px rgba(91, 33, 182, 0.18);
  clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 50%, calc(100% - 6px) 100%, 0 100%, 0 0);
  transition:
    transform 0.16s ease,
    box-shadow 0.16s ease,
    filter 0.16s ease;
  -webkit-tap-highlight-color: transparent;
}
.lobby-nav-back__glyph {
  display: grid;
  place-items: center;
  width: 22px;
  height: 20px;
  border-radius: 4px;
  color: var(--lobby-laser-indigo, #a78bfa);
  background:
    radial-gradient(circle at 35% 30%, rgba(167, 139, 250, 0.32), transparent 58%),
    rgba(6, 3, 18, 0.92);
  box-shadow:
    inset 0 0 0 1px rgba(129, 140, 248, 0.32),
    0 0 8px rgba(124, 58, 237, 0.2);
