/* Космические капсулы — главные действия лобби */
.lobby-capsule {
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin: 0;
  padding: 6px 12px 6px 6px;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  border: 1.5px solid transparent;
  border-radius: 999px;
  background-clip: padding-box;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    filter 0.18s ease,
    border-color 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}
.lobby-capsule:disabled,
.lobby-capsule--disabled {
