.lobby-capsule-glyph-orbit--a {
  transform-origin: 22px 22px;
  animation: lobby-orbit-spin 9s linear infinite;
}
.lobby-capsule-glyph-orbit--b {
  transform-origin: 22px 22px;
  animation: lobby-orbit-spin 12s linear infinite reverse;
}
.lobby-capsule-glyph-orbit--c {
  transform-origin: 22px 22px;
  animation: lobby-orbit-spin 15s linear infinite;
}
.lobby-capsule-glyph-pulse {
  transform-origin: 22px 22px;
  animation: lobby-portal-pulse 2.4s ease-in-out infinite;
}
@keyframes lobby-orbit-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
@keyframes lobby-portal-pulse {
  0%,
  100% {
    transform: scale(0.92);
    opacity: 0.28;
  }
  50% {
    transform: scale(1.06);
    opacity: 0.55;
  }
}

