    background:
      radial-gradient(ellipse 118% 96% at 50% 44%, rgba(15, 23, 42, 0.08) 28%, rgba(15, 23, 42, 0.82) 100%),
      linear-gradient(180deg, rgba(15, 23, 42, 0.22) 0%, rgba(15, 23, 42, 0.62) 100%);
  }
  .lobby-screen--entry .lobby-screen__layout {
    width: 100%;
    max-width: 100%;
    padding-top: max(10px, env(safe-area-inset-top, 0px));
    padding-left: max(12px, env(safe-area-inset-left, 0px));
    padding-right: max(12px, env(safe-area-inset-right, 0px));
