  .lobby-capsule--last-party .lobby-capsule__hint {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .lobby-capsule__glyph {
    width: 42px;
    height: 42px;
  }
  .lobby-capsule-glyph-svg {
    width: 40px;
    height: 40px;
  }
  .lobby-capsule__title {
    font-size: 15px;
  }
  .lobby-capsule__body {
    min-width: 0;
  }
}

/*
 * Моб. landscape (низкий viewport): портрет 200px съедает высоту → кнопки ниже сгиба и
 * часто «невидимы» (скролл ломается touch-action на body). Каст слева, действия справа.
 */
@media (max-width: 1024px) and (orientation: landscape) and (max-height: 500px) {
  .lobby-screen--entry .lobby-screen__layout.lobby-screen__layout--entry {
    padding-top: max(6px, env(safe-area-inset-top, 0px));
    padding-bottom: max(12px, env(safe-area-inset-bottom, 0px));
    padding-left: max(10px, env(safe-area-inset-left, 0px));
    padding-right: max(10px, env(safe-area-inset-right, 0px));
    gap: 6px;
  }
  .lobby-screen--entry .lobby-screen__top-bar {
    padding: 2px 0 4px;
    margin-bottom: 0;
  }
  .lobby-screen--entry .lobby-screen__entry-main {
    flex-direction: row;
    align-items: flex-start;
    justify-content: center;
    gap: 14px;
    max-width: min(720px, 100%);
    margin: 0 auto;
  }
  .lobby-screen--entry .lobby-screen__hero-col {
    flex: 0 0 auto;
    width: auto;
    max-width: none;
    position: sticky;
    top: 4px;
    align-self: flex-start;
  }
  .lobby-screen--entry .lobby-screen__hero {
    width: min(112px, 32vh, 28vw);
    border-radius: 14px;
    padding: 2px;
  }
  .lobby-screen--entry .lobby-screen__hero img {
    border-radius: 12px;
  }
  .lobby-screen--entry .lobby-screen__content {
    flex: 1 1 auto;
    min-width: 0;
    max-width: min(360px, 100%);
    align-items: stretch;
    gap: 10px;
    padding-bottom: 8px;
  }
  .lobby-screen--entry .lobby-screen__title {
    font-size: 1.35rem;
    align-self: flex-start;
  }
  .lobby-screen--entry .lobby-online-legend,
  .lobby-screen--entry .lobby-entry-player,
  .lobby-screen--entry .lobby-entry-menu,
  .lobby-screen--entry .lobby-entry-join,
  .lobby-screen--entry .lobby-last-party-fold {
    width: 100%;
    max-width: 100%;
    align-self: stretch;
  }
  .lobby-screen--entry .lobby-entry-menu .lobby-capsule,
  .lobby-screen--entry .lobby-entry-join .lobby-capsule,
  .lobby-screen--entry .lobby-last-party-fold .lobby-capsule {
    max-width: 100%;
  }
  .lobby-screen--entry .lobby-screen__aura-img {
    opacity: 0.28;
    transform: translate(-50%, -50%) scale(1.15);
  }
}

@media (prefers-reduced-motion: reduce) {
  .lobby-capsule {
    transition: none;
  }
  .lobby-capsule--hall:hover:not(:disabled),
  .lobby-capsule--create:hover:not(:disabled),
  .lobby-capsule--join:hover:not(:disabled),
  .lobby-capsule--launch:hover:not(:disabled),
  .lobby-capsule--back:hover:not(:disabled),
  .lobby-capsule--last-party:hover:not(:disabled) {
    transform: none;
  }
  .lobby-capsule-glyph-orbit--a,
  .lobby-capsule-glyph-orbit--b,
  .lobby-capsule-glyph-orbit--c,
  .lobby-capsule-glyph-pulse {
    animation: none;
  }
}

@media (min-width: 1025px) {
  .lobby-screen__layout--entry {
    max-width: 960px;
    min-height: min(100%, 100dvh);
    gap: 12px;
    padding: 20px 40px 32px;
  }
  .lobby-screen__top-bar {
    max-width: 960px;
  }
  .lobby-screen__entry-main {
    flex-direction: row;
    align-items: center;
    justify-content: center;
    gap: 36px;
    max-width: 960px;
  }
  .lobby-screen__hero-col {
    flex: 0 0 40%;
    max-width: 40%;
    align-items: center;
  }
  .lobby-screen__hero {
    width: min(100%, 320px);
    max-width: 320px;
  }
  .lobby-screen__content {
    flex: 1 1 60%;
    max-width: 60%;
    align-items: center;
    justify-content: center;
  }
}
@media (prefers-reduced-motion: reduce) {
  .lobby-screen__aura-img {
    filter: blur(34px) saturate(1.2) brightness(0.68);
    transform: translate(-50%, -50%);
  }
}

