/* Капсулы главного меню */
.menu-capsule {
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  margin: 0;
  padding: 6px 12px 6px 6px;
  font-family: inherit;
  text-align: left;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  border: 1.5px solid transparent;
  border-radius: 999px;
  background-clip: padding-box;
  transition:
    transform 0.18s ease,
    box-shadow 0.18s ease,
    filter 0.18s ease,
    border-color 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}
.menu-capsule:focus-visible {
  outline: 2px solid rgba(34, 211, 238, 0.65);
  outline-offset: 2px;
}
.menu-capsule:focus:not(:focus-visible) {
  outline: none;
}
.menu-capsule:disabled,
.menu-capsule--disabled {
  opacity: 0.48;
  cursor: not-allowed;
  filter: saturate(0.75);
}
.menu-capsule:hover:not(:disabled):not(.menu-capsule--disabled) {
  transform: translateY(-1px);
  filter: brightness(1.06);
}
.menu-capsule__glyph {
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  color: var(--lobby-laser-cyan-hot);
  transition:
    width 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    height 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
.menu-capsule-glyph-svg {
  width: 44px;
  height: 44px;
  display: block;
  transition:
    width 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    height 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}
