/* Split Capsule B4 — mode crest on center beam (rollback v2-left-rail: _rollback/) */
.menu-split-capsule {
  position: relative;
  width: 100%;
  --menu-mode-glyph-size: 51px;
  --menu-mode-glyph-svg-size: 48px;
  --menu-mode-stack-y: 36%;
  --menu-mode-arc-band: 28px;
  --menu-mode-arc-gap: 0px;
  --menu-mode-arc-lift: 12px;
  --menu-legend-art-size-full: min(100%, 268px);
