}
.menu-split-capsule--has-satellite {
  margin-top: 10px;
}
.menu-split-capsule--b4 .menu-split-capsule__shell {
  min-height: 88px;
}
.menu-split-capsule__shell {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  width: 100%;
  min-height: 76px;
  border-radius: 999px;
  overflow: visible;
  isolation: isolate;
  transition:
    border-radius 0.28s cubic-bezier(0.33, 1, 0.68, 1),
    box-shadow 0.34s ease;
}
