/* Offline theme: hybrid D+ — body plum / acid raspberry; glyphs keep indigo.
 * Resume half titles keep bluish-cyan. Arc pill muted for ОФЛАЙН readability.
 * Snapshots: indigo = _rollback/menu-offline-theme-indigo-slate.css;
 * amber = _rollback/menu-offline-theme-amber-bronze.css */
.menu-split-capsule--offline .menu-split-capsule__shell {
  border: 1.5px solid transparent;
  background:
    linear-gradient(102deg, rgba(22, 4, 28, 0.98) 0%, rgba(8, 2, 16, 1) 100%) padding-box,
    linear-gradient(
      128deg,
      #8b0d2e 0%,
      #5b1494 18%,
      #9a1260 38%,
      #1a6b8a 52%,
      #2e0d6e 68%,
      #9a1260 84%,
      #8b0d2e 100%
    ) border-box;
  box-shadow:
    inset 0 1px 0 rgba(148, 34, 235, 0.22),
    inset 0 -3px 10px rgba(8, 2, 16, 0.55),
    0 2px 16px rgba(0, 0, 0, 0.48),
    0 0 0 1px rgba(90, 12, 56, 0.45),
    0 0 20px rgba(120, 16, 70, 0.28),
    0 0 14px rgba(80, 18, 120, 0.22);
}
.menu-split-capsule__mode-crest-anchor {
  position: absolute;
  left: 50%;
  top: 0;
  height: 100%;
  width: 0;
  z-index: 5;
  pointer-events: none;
}
.menu-split-capsule__mode-crest-stack {
  position: absolute;
  left: 0;
  top: var(--menu-mode-stack-y, 36%);
  z-index: 6;
  transform: translate(-50%, calc(-50% + 2px));
  pointer-events: none;
}
.menu-split-capsule__mode-crest-head {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: calc(var(--menu-mode-glyph-size) + 44px);
  height: auto;
  margin: 0 auto;
}
.menu-split-capsule__mode-glyph-cluster {
  position: relative;
  flex-shrink: 0;
  width: 100%;
  height: var(--menu-mode-glyph-size);
}
.menu-split-capsule__mode-glyph {
  position: relative;
  left: auto;
  top: auto;
  z-index: 2;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  width: var(--menu-mode-glyph-size, 34px);
  height: var(--menu-mode-glyph-size, 34px);
  margin: 0 auto;
  border-radius: 50%;
  transform: translateY(2px);
}
.menu-split-capsule__mode-glyph-btn {
  padding: 0;
  border: none;
  cursor: pointer;
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  -webkit-touch-callout: none;
  user-select: none;
  appearance: none;
  -webkit-appearance: none;
  transition:
    transform 0.22s ease,
    box-shadow 0.22s ease,
    filter 0.22s ease;
}
.menu-split-capsule__mode-glyph-btn:hover {
  filter: brightness(1.18) saturate(1.08);
  transform: translateY(2px) scale(1.07);
}
.menu-split-capsule__mode-glyph-btn:focus:not(:focus-visible) {
  outline: none;
}
.menu-split-capsule__mode-glyph-btn:focus-visible {
  outline: 2px solid rgba(103, 232, 249, 0.85);
  outline-offset: 3px;
}
.menu-split-capsule__mode-glyph--legend-open {
  filter: brightness(1.14);
  box-shadow:
    inset 0 0 0 1px rgba(192, 132, 252, 0.48),
    0 0 16px rgba(168, 85, 247, 0.38);
}
.menu-split-capsule--online .menu-split-capsule__mode-glyph--legend-open {
  box-shadow:
    inset 0 0 0 1px rgba(192, 132, 252, 0.48),
    0 0 18px rgba(168, 85, 247, 0.4);
}
/* Offline crest glyph: розовый → сиреневый → фиолет → сине-голубой */
@keyframes menu-offline-glyph-chroma-fill {
  0%,
  100% {
    fill: #ff5ec8;
  }
  25% {
    fill: #c4b5fd;
  }
  50% {
    fill: #a78bfa;
  }
  75% {
    fill: #38bdf8;
  }
}
@keyframes menu-offline-glyph-chroma-stroke {
  0%,
  100% {
    stroke: #ff5ec8;
  }
  25% {
    stroke: #c4b5fd;
  }
  50% {
    stroke: #a78bfa;
