@keyframes menu-solo-pill-label-in {
  from {
    opacity: 0;
    filter: blur(1.5px);
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0);
  }
}
@keyframes menu-solo-watermark-ghost-breathe {
  0%,
  100% {
    opacity: 0.72;
    transform: translate3d(-50%, calc(-50% + 1px), 0) scaleX(1.2) scaleY(1);
    filter: brightness(0.96);
  }
  50% {
    opacity: 1;
    transform: translate3d(-50%, calc(-50% + 1px), 0) scaleX(1.27) scaleY(1.05);
    filter: brightness(1.12);
  }
}
@keyframes menu-solo-watermark-scan-breathe {
  0%,
  100% {
    opacity: 0.55;
    transform: translateY(-50%) scaleX(0.94);
  }
  50% {
    opacity: 1;
    transform: translateY(-50%) scaleX(1.02);
  }
}
/* Offline: tips → up (full) → tips. Online: tips → down (full) → tips. (только «без слов») */
@keyframes menu-solo-watermark-pill-up {
  0%,
  10% {
    transform: translate3d(-50%, -50%, 0) scale(1);
    opacity: 0.78;
    z-index: 3;
    filter: brightness(1);
  }
  22% {
    transform: translate3d(-50%, calc(-50% - 8px), 0) scale(1.08);
    opacity: 0.92;
    z-index: 8;
    filter: brightness(1.06);
  }
  32%,
  52% {
    transform: translate3d(-50%, calc(-50% - 20px), 0) scale(1.2);
    opacity: 1;
    z-index: 8;
    filter: brightness(1.14);
  }
  64%,
  100% {
    transform: translate3d(-50%, -50%, 0) scale(1);
    opacity: 0.78;
    z-index: 3;
    filter: brightness(1);
  }
}
@keyframes menu-solo-watermark-pill-down {
  0%,
  10% {
    transform: translate3d(-50%, -50%, 0) scale(1);
    opacity: 0.78;
    z-index: 3;
    filter: brightness(1);
  }
  22% {
    transform: translate3d(-50%, calc(-50% + 9px), 0) scale(1.08);
    opacity: 0.92;
    z-index: 8;
    filter: brightness(1.06);
  }
  32%,
  52% {
    transform: translate3d(-50%, calc(-50% + 22px), 0) scale(1.18);
    opacity: 1;
    z-index: 8;
    filter: brightness(1.12);
  }
  64%,
  100% {
    transform: translate3d(-50%, -50%, 0) scale(1);
    opacity: 0.78;
    z-index: 3;
    filter: brightness(1);
  }
}
/* полный вид: каплюля закреплена под глифом, только лёгкое «дыхание» масштаба */
@keyframes menu-solo-watermark-pill-pulse {
  0%,
  100% {
    transform: translate3d(-50%, calc(-50% + 34px), 0) scale(0.94);
    opacity: 0.88;
    filter: brightness(1);
  }
  50% {
    transform: translate3d(-50%, calc(-50% + 34px), 0) scale(1.06);
    opacity: 1;
    filter: brightness(1.08);
  }
}
@media (prefers-reduced-motion: reduce) {
  .menu-split-capsule__solo-watermark-ghost,
