  pointer-events: none;
  opacity: 0.75;
  animation: menu-glyph-laser-ring 2.6s ease-in-out infinite;
}
.menu-split-capsule__mode-glyph--online::after {
  border-color: rgba(192, 132, 252, 0.58);
