    0 0 10px rgba(129, 140, 248, 0.42),
    0 0 16px rgba(99, 102, 241, 0.22);
}
@keyframes menu-glyph-laser-ring {
  0%,
  100% {
    transform: scale(0.92);
    opacity: 0.4;
  }
  50% {
    transform: scale(1.08);
    opacity: 0.9;
  }
}
.menu-split-capsule__half:hover .menu-split-capsule__glyph {
  filter: brightness(1.14) saturate(1.08) drop-shadow(0 0 8px rgba(255, 255, 255, 0.25));
}
.menu-split-capsule__half--main:hover .menu-split-capsule__glyph {
  transform: translateX(-7px) scale(1.06);
}
.menu-split-capsule__half--resume:hover .menu-split-capsule__glyph {
  transform: translateX(7px) scale(1.06);
}
.menu-split-capsule__glyph--stack {
  width: 36px;
  height: 36px;
}
.menu-split-capsule__glyph--stack .menu-capsule-glyph-svg {
  width: 34px;
  height: 34px;
}
.menu-split-capsule__glyph--sm {
  width: 34px;
  height: 34px;
}
.menu-split-capsule__glyph--sm .menu-capsule-glyph-svg {
  width: 32px;
  height: 32px;
}
.menu-split-capsule__body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.menu-split-capsule__title {
  font-family: 'Exo 2', 'Orbitron', ui-sans-serif, system-ui, sans-serif;
  font-size: 11px;
  font-weight: 800;
  font-style: normal;
  letter-spacing: 0.12em;
  line-height: 1.1;
  text-transform: uppercase;
  font-feature-settings: 'kern' 1;
  /* компенсация трекинга, чтобы блок не «уезжал» вправо */
