  margin-inline-end: -0.12em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.menu-split-capsule__hint {
  font-family: 'Exo 2', 'JetBrains Mono', ui-monospace, monospace;
  font-size: 8px;
  font-weight: 700;
  font-style: normal;
  letter-spacing: 0.14em;
  line-height: 1.2;
  text-transform: uppercase;
  font-feature-settings: 'kern' 1;
  padding-inline-end: 0.14em;
  margin-inline-end: -0.14em;
  opacity: 0.92;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.menu-split-capsule__satellite {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 8;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.menu-split-capsule__satellite-ring {
  position: absolute;
  inset: -5px -8px;
  border: 1px dashed rgba(34, 211, 238, 0.35);
  border-radius: 999px;
  animation: lobby-orbit-spin 14s linear infinite;
  opacity: 0.75;
}
.menu-split-capsule__satellite-code {
  position: relative;
  display: inline-block;
  padding: 2px 9px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--lobby-laser-cyan-hot);
  text-shadow:
    0 0 8px rgba(103, 232, 249, 0.65),
    0 0 14px rgba(34, 211, 238, 0.35);
  border: 1px solid rgba(34, 211, 238, 0.42);
  border-radius: 999px;
  background:
    radial-gradient(circle at 30% 30%, rgba(34, 211, 238, 0.22), transparent 55%),
    rgba(4, 20, 32, 0.94);
  box-shadow:
    0 0 12px rgba(34, 211, 238, 0.28),
    inset 0 1px 0 rgba(186, 230, 253, 0.12);
  animation: menu-satellite-float 3.2s ease-in-out infinite;
}
@keyframes menu-satellite-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-2px);
  }
}

/* ==========================================================================
   Game info badge — plasma / hologram skin (.game-info-badge-plasma on root)
   Палитра: глубокий фиолет, индиго, синий, чёрный, сирень, лаванда, циан,
   кислотная малина — без бордо, золота и «землистых» оттенков.
   Hologram: вращающаяся iridescent-обводка (conic + glow) + фиолетовая «рамка»
   (padding между обводкой и экраном: blobs/vignette/screen) + экран (> div).
   ========================================================================== */

@property --plasma-holo-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes plasma-holo-ring-shimmer {
  0%,
  100% {
    opacity: 0.9;
    filter: hue-rotate(-10deg) saturate(1.32) brightness(1.04);
  }
  33% {
    opacity: 1;
    filter: hue-rotate(32deg) saturate(1.52) brightness(1.1);
  }
  66% {
    opacity: 0.96;
    filter: hue-rotate(16deg) saturate(1.42) brightness(1.07);
  }
}

@keyframes plasma-screen-top-holo-glow {
  0%,
  100% {
    opacity: 0.84;
    box-shadow:
      0 0 4px rgba(124, 58, 237, 0.48),
      0 0 9px rgba(147, 51, 234, 0.36),
      0 0 14px rgba(167, 139, 250, 0.22);
  }
  50% {
    opacity: 1;
    box-shadow:
      0 0 7px rgba(124, 58, 237, 0.78),
      0 0 14px rgba(147, 51, 234, 0.62),
      0 0 22px rgba(196, 181, 253, 0.48),
      0 0 30px rgba(124, 58, 237, 0.32);
  }
}

@keyframes plasma-holo-border-spin {
  to {
    --plasma-holo-angle: 360deg;
  }
}
/* Phone landscape instrument ensemble */
@keyframes ls-chassis-bus-pulse {
  0%,
  100% {
    opacity: 0.65;
    filter: brightness(1) drop-shadow(0 0 4px rgba(34, 211, 238, 0.45));
  }
  50% {
    opacity: 1;
    filter: brightness(1.35) drop-shadow(0 0 10px rgba(34, 211, 238, 0.85));
  }
}
@keyframes ls-chassis-edge-pulse {
  0%,
  100% {
    opacity: 0.78;
  }
  50% {
    opacity: 1;
  }
}
@keyframes ls-chassis-hud-breathe {
  0%,
  100% {
    box-shadow:
      inset 0 1px 0 rgba(165, 243, 252, 0.28),
      inset 0 0 24px rgba(34, 211, 238, 0.14),
      inset 0 0 0 1px rgba(34, 211, 238, 0.35),
      0 0 14px rgba(34, 211, 238, 0.4),
      0 0 28px rgba(124, 58, 237, 0.35);
  }
  50% {
    box-shadow:
      inset 0 1px 0 rgba(207, 250, 254, 0.4),
      inset 0 0 32px rgba(34, 211, 238, 0.22),
      inset 0 0 0 1px rgba(103, 232, 249, 0.55),
      0 0 20px rgba(34, 211, 238, 0.55),
      0 0 36px rgba(124, 58, 237, 0.45);
  }
}
@keyframes ls-plasma-screen-prism-shift {
  /* Полоски (слой 1) стоят; спектр (слой 2) едет по X; низ — лёгкий дрейф */
  0%,
  100% {
    background-position: 0 0, 0% 50%, 0% 40%;
  }
  50% {
    background-position: 0 0, 100% 50%, 70% 20%;
  }
}

@keyframes plasma-badge-frame-pulse {
  0%,
  100% {
    box-shadow:
      inset 0 1px 0 rgba(221, 214, 254, 0.11),
      inset 0 0 40px rgba(99, 102, 241, 0.08),
      0 0 22px rgba(34, 211, 238, 0.22),
      0 0 34px rgba(124, 58, 237, 0.38),
      0 0 48px rgba(147, 51, 234, 0.3),
      0 0 58px rgba(196, 181, 253, 0.18),
      0 0 64px rgba(129, 140, 248, 0.1),
      0 8px 30px rgba(3, 7, 18, 0.62);
  }
  50% {
    box-shadow:
      inset 0 1px 0 rgba(221, 214, 254, 0.16),
      inset 0 0 52px rgba(99, 102, 241, 0.14),
      0 0 28px rgba(34, 211, 238, 0.36),
      0 0 42px rgba(124, 58, 237, 0.52),
      0 0 58px rgba(147, 51, 234, 0.42),
      0 0 72px rgba(196, 181, 253, 0.28),
      0 0 82px rgba(167, 139, 250, 0.2),
      0 10px 36px rgba(3, 7, 18, 0.68);
  }
}

@keyframes plasma-holo-shimmer {
  0%,
  100% {
    opacity: 0.28;
    transform: translateX(-14%) skewX(-8deg);
  }
  50% {
    opacity: 0.56;
    transform: translateX(14%) skewX(-8deg);
  }
}

.game-table-root.game-info-badge-plasma {
  --cosmo-black: #030712;
  --cosmo-void: #050816;
  --cosmo-indigo-deep: #1e1b4b;
  --cosmo-indigo: #312e81;
  --cosmo-purple: #5b21b6;
  --cosmo-violet: #7c3aed;
  --cosmo-lilac: #a78bfa;
  --cosmo-lavender: #c4b5fd;
  --cosmo-blue: #2563eb;
  --cosmo-sky: #38bdf8;
  --cosmo-cyan: #22d3ee;
  --cosmo-cyan-bright: #67e8f9;
  --cosmo-raspberry: #f472b6;
  --cosmo-acid-pink: #ff49a0;
  --plasma-badge-scan: repeating-linear-gradient(
    0deg,
    transparent 0 2px,
    rgba(3, 7, 18, 0.2) 2px 3px
  );
  --plasma-badge-vignette: radial-gradient(
    ellipse 96% 90% at 50% 50%,
    transparent 36%,
    rgba(91, 33, 182, 0.1) 70%,
    rgba(3, 7, 18, 0.58) 100%
  );
  --plasma-badge-blob-a: radial-gradient(
    circle at 12% 16%,
    rgba(167, 139, 250, 0.22) 0%,
    transparent 48%
  );
  --plasma-badge-blob-b: radial-gradient(
    circle at 78% 22%,
    rgba(196, 181, 253, 0.24) 0%,
    transparent 46%
  );
  --plasma-badge-blob-c: radial-gradient(
    circle at 88% 78%,
    rgba(124, 58, 237, 0.16) 0%,
    transparent 44%
  );
  --plasma-badge-blob-d: radial-gradient(
    circle at 24% 84%,
    rgba(147, 51, 234, 0.24) 0%,
    transparent 42%
  );
  --plasma-badge-screen: linear-gradient(
    152deg,
    rgba(36, 28, 88, 0.98) 0%,
    rgba(5, 8, 22, 0.99) 34%,
    rgba(28, 14, 62, 0.98) 68%,
    rgba(42, 18, 82, 0.97) 100%
  );
  --plasma-badge-holo-ring: conic-gradient(
    from var(--plasma-holo-angle),
    #9333ea 0deg,
    #a855f7 26deg,
    #c084fc 52deg,
    #7c3aed 78deg,
    #6d28d9 104deg,
    #8b5cf6 128deg,
    #22d3ee 152deg,
    #67e8f9 168deg,
    #6366f1 184deg,
    #a78bfa 200deg,
    #ddd6fe 216deg,
    #9333ea 232deg,
    #7c3aed 248deg,
    #581c87 264deg,
    #c4b5fd 280deg,
    #38bdf8 296deg,
    #818cf8 312deg,
    #9333ea 336deg,
    #a855f7 360deg
  );
  --plasma-screen-top-holo-ring: conic-gradient(
    from var(--plasma-holo-angle),
    #6d28d9 0deg,
    #7c3aed 32deg,
    #9333ea 64deg,
    #a855f7 96deg,
    #c084fc 128deg,
    #8b5cf6 160deg,
    #a78bfa 192deg,
    #e9d5ff 224deg,
    #9333ea 256deg,
    #581c87 288deg,
    #6366f1 320deg,
    #6d28d9 360deg
  );
  /* Обводка: верх/бока 3px, низ 1px (утончена) */
  --plasma-badge-holo-pad: 3px 3px 1px 3px;
  --plasma-screen-bleed-x: 13px;
  --plasma-screen-gap-above: 7px;
  --plasma-deal-meta-pad-y: 1px;
  --plasma-deal-meta-gap-screen: 2px;
  --plasma-deal-meta-pad-top: 3px;
  --plasma-deal-meta-row-h: 14px;
  --plasma-deal-meta-font-size: 10px;
  --plasma-deal-meta-label-font-size: 12px;
  --plasma-deal-meta-value-font-size: 14px;
  --plasma-deal-meta-value-scale-x: 1.14;
  --plasma-deal-meta-mode-font-size: 12px;
  --plasma-deal-meta-mode-shift-y-portrait: 0px;
  --plasma-deal-meta-mode-shift-y-landscape: 3px;
  --plasma-deal-meta-shift-y: 2px;
  --plasma-screen-radius-bottom-meta: 12px;
  /* +3px к высоте внешнего бейджа (.game-info-left-section) */
  --plasma-badge-extra-h: 6px;
  /* Portrait: та же высота, что у бейджа без мета (экранчик внизу, зазор — между метой и экраном) */
  --plasma-badge-portrait-pad-top-full: calc(11px + var(--plasma-badge-extra-h));
  --plasma-badge-portrait-pad-bottom-full: 4px;
  --plasma-badge-portrait-screen-body-h: calc(var(--plasma-screen-gap-above) + 2.5px + 4px + 22px);
  --plasma-badge-portrait-h: calc(
    var(--plasma-badge-portrait-pad-top-full) + var(--plasma-badge-portrait-pad-bottom-full) +
      var(--plasma-badge-portrait-screen-body-h)
  );
  /* С мета: +11px к базе = extra-h (6) + holo (5), в т.ч. запрошенные +2px */
  --plasma-badge-portrait-h-meta: calc(var(--plasma-badge-portrait-h) + var(--plasma-badge-extra-h) + 5px);
  --plasma-badge-landscape-h: calc(var(--mobile-landscape-upper-badge-h, 67.2px) - 3px);
  --plasma-badge-extra-w: 20px;
  --plasma-badge-base-min-w-mobile: 148px;
  --plasma-badge-base-max-w: 280px;
  --plasma-badge-min-w-mobile: calc(var(--plasma-badge-base-min-w-mobile) + var(--plasma-badge-extra-w));
  --plasma-badge-max-w: calc(var(--plasma-badge-base-max-w) + var(--plasma-badge-extra-w));
  /* Portrait: зазор от toolbar и правого края (toolbar ≈ header-pad + 4 кнопки + strip-pad) */
  --plasma-badge-portrait-h-gap: max(8px, env(safe-area-inset-right, 0px));
  --plasma-badge-portrait-toolbar-strip-w: calc(
    12px + 4 * var(--portrait-header-toolbar-btn-size, 26px) + 3 * 4px
  );
  --plasma-badge-portrait-pad-left: calc(
    var(--game-table-padding, 6px) + var(--plasma-badge-portrait-toolbar-strip-w) +
      var(--plasma-badge-portrait-h-gap)
  );
  --plasma-badge-portrait-pad-right: var(--plasma-badge-portrait-h-gap);
  /* Landscape: зазор у правого края (симметрия portrait h-gap) */
  --plasma-badge-landscape-h-gap: max(8px, env(safe-area-inset-right, 0px));
}

/*
 * Phone LS · gap meta↔экранчик: после .game-info-badge-plasma (иначе 2px перебивает).
 * Реальный margin раньше брал --plasma-screen-gap-above (7px) — см. фикс в @media max-width 1024.
 */
.game-table-root.game-info-badge-plasma.viewport-mobile.viewport-mobile-landscape:not(
    .viewport-mobile-landscape-mid
  ) {
  --plasma-deal-meta-gap-screen: calc(var(--plasma-screen-gap-above, 7px) - 2px);
}
.game-table-root.game-info-badge-plasma.viewport-mobile.viewport-mobile-landscape.viewport-mobile-landscape-after-short:not(
    .viewport-mobile-landscape-mid
  ) {
  --plasma-deal-meta-gap-screen: calc(var(--plasma-screen-gap-above, 7px) - 2px);
}

.game-table-root.game-info-badge-plasma:not(.viewport-mobile) {
  --plasma-screen-bleed-x: 12px;
}

