 * Цикл 22 с — паттерн не укладывается в «тик-так».
 */
@keyframes plasma-screen-glint-sweep {
  0%,
  3%,
  100% {
    opacity: 0;
    transform: translateX(-125%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1);
  }

  /* A — мягкий ранний, слева направо, голубой */
  4% {
    opacity: 0.16;
    transform: translateX(-125%) skewX(-9deg) scale(0.96);
    filter: hue-rotate(0deg) saturate(1.05);
  }
  6% {
    opacity: 0.72;
    transform: translateX(-125%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1.08);
  }
  17% {
    opacity: 0.64;
    transform: translateX(235%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1.05);
  }
  19% {
    opacity: 0;
    transform: translateX(235%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1);
  }

  /* B — быстрый узкий «шёпот», сиреневый сдвиг */
  27% {
    opacity: 0;
    transform: translateX(-125%) skewX(-6deg) scale(0.82);
    filter: hue-rotate(28deg) saturate(1.12);
  }
  28% {
    opacity: 0.46;
    transform: translateX(-125%) skewX(-6deg) scale(0.82);
    filter: hue-rotate(28deg) saturate(1.12);
  }
  33% {
    opacity: 0.38;
    transform: translateX(235%) skewX(-6deg) scale(0.82);
    filter: hue-rotate(28deg) saturate(1.1);
  }
  35% {
    opacity: 0;
    transform: translateX(235%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1);
  }

  /* C — главный медленный, крупный, с провалом в середине */
  42% {
    opacity: 0;
    transform: translateX(-125%) skewX(-11deg) scale(1.08);
    filter: hue-rotate(-8deg) saturate(1.1);
  }
  44% {
    opacity: 0.92;
    transform: translateX(-125%) skewX(-11deg) scale(1.08);
    filter: hue-rotate(-8deg) saturate(1.12);
  }
  50% {
    opacity: 0.74;
    transform: translateX(48%) skewX(-11deg) scale(1.05);
    filter: hue-rotate(-6deg) saturate(1.08);
  }
  61% {
    opacity: 0.88;
    transform: translateX(235%) skewX(-11deg) scale(1.08);
    filter: hue-rotate(-8deg) saturate(1.1);
  }
  63% {
    opacity: 0;
    transform: translateX(235%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1);
  }

  /* D — поздний слабый, компактный */
  70% {
    opacity: 0;
    transform: translateX(-125%) skewX(-7deg) scale(0.88);
    filter: hue-rotate(14deg) saturate(1.05);
  }
  72% {
    opacity: 0.32;
    transform: translateX(-125%) skewX(-7deg) scale(0.88);
    filter: hue-rotate(14deg) saturate(1.05);
  }
  79% {
    opacity: 0.26;
    transform: translateX(235%) skewX(-7deg) scale(0.88);
    filter: hue-rotate(14deg) saturate(1.02);
  }
  81% {
    opacity: 0;
    transform: translateX(235%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1);
  }

  /* E — редкий: справа налево, крупный, индиго-синий */
  84% {
    opacity: 0;
    transform: translateX(235%) skewX(10deg) scale(1.16);
    filter: hue-rotate(-38deg) saturate(1.18);
  }
  85% {
    opacity: 0.78;
    transform: translateX(235%) skewX(10deg) scale(1.16);
    filter: hue-rotate(-38deg) saturate(1.2);
  }
  93% {
    opacity: 0.68;
    transform: translateX(-125%) skewX(10deg) scale(1.14);
    filter: hue-rotate(-34deg) saturate(1.15);
  }
  95% {
    opacity: 0;
    transform: translateX(-125%) skewX(-9deg) scale(1);
    filter: hue-rotate(0deg) saturate(1);
  }
}

/* Призрачный слой: другой угол, другие моменты, иногда навстречу */
@keyframes plasma-screen-glint-ghost {
  0%,
  10%,
  100% {
    opacity: 0;
    transform: translateX(-120%) rotate(-118deg) skewX(7deg) scale(0.78);
    filter: hue-rotate(42deg) saturate(1.08);
  }

  /* микро-проблеск — короткий, мелкий, лавандовый */
  11% {
    opacity: 0.34;
    transform: translateX(-120%) rotate(-118deg) skewX(7deg) scale(0.72);
    filter: hue-rotate(52deg) saturate(1.15);
  }
  13% {
    opacity: 0;
    transform: translateX(60%) rotate(-118deg) skewX(7deg) scale(0.72);
    filter: hue-rotate(52deg) saturate(1.1);
  }

  /* средний — быстро справа налево, средний размер */
  46% {
    opacity: 0;
    transform: translateX(230%) rotate(-118deg) skewX(5deg) scale(0.94);
    filter: hue-rotate(18deg) saturate(1.12);
  }
  47% {
    opacity: 0.58;
    transform: translateX(230%) rotate(-118deg) skewX(5deg) scale(0.94);
    filter: hue-rotate(18deg) saturate(1.14);
  }
  52% {
    opacity: 0.48;
    transform: translateX(-125%) rotate(-118deg) skewX(5deg) scale(0.92);
    filter: hue-rotate(22deg) saturate(1.1);
  }
  54% {
    opacity: 0;
    transform: translateX(-125%) rotate(-118deg) skewX(7deg) scale(0.78);
    filter: hue-rotate(42deg) saturate(1.08);
  }

  /* редкий поздний — медленный, широкий, холодный indigo */
  85% {
    opacity: 0;
    transform: translateX(-130%) rotate(-118deg) skewX(9deg) scale(1.22);
    filter: hue-rotate(-48deg) saturate(1.2);
  }
  87% {
    opacity: 0.52;
    transform: translateX(-130%) rotate(-118deg) skewX(9deg) scale(1.22);
    filter: hue-rotate(-48deg) saturate(1.22);
  }
  96% {
    opacity: 0.44;
    transform: translateX(240%) rotate(-118deg) skewX(9deg) scale(1.18);
    filter: hue-rotate(-42deg) saturate(1.16);
  }
  98% {
    opacity: 0;
    transform: translateX(240%) rotate(-118deg) skewX(7deg) scale(0.78);
    filter: hue-rotate(42deg) saturate(1.08);
  }
}

